"""Durable project primitives; no provider credentials or global runtime state."""
from __future__ import annotations
import contextlib
import datetime as dt
import fcntl
import hashlib
import json
import math
import os
from pathlib import Path
import re
import shutil
import stat
import tempfile
from .verified_files import source_identity, verified_operation

SCHEMA = "upstate.scientific-workbench/v1"
INVEST_VERSION = "3.20.0"
INVEST_SOURCE = {
    "repository": "https://github.com/natcap/invest",
    "ref": "3.20.0",
    "ndr_blob": "f518b2867d4a327675fcb1c9b4ba56f29b12188d",
    "sdr_blob": "0cac27add172011df367ff8026427dbbdbcda5b2",
}
ROLES = ("DEM", "NLCD", "PRECIPITATION", "R_FACTOR", "K_FACTOR")
MODELS = ("ndr", "sdr")
MODEL_ROLES = {
    "ndr": ("DEM", "NLCD", "PRECIPITATION"),
    "sdr": ("DEM", "NLCD", "R_FACTOR", "K_FACTOR"),
}
MODEL_OUTPUTS = {
    "nitrogen_export": ("ndr", "n_total_export"),
    "phosphorus_export": ("ndr", "p_surface_export"),
    "sediment_export": ("sdr", "sed_export"),
}
SOURCE_IDS = ROLES + ("PROTECTED_LANDS", "PARCEL", "NHD", "NWI", "LS_FACTOR")
MAP_IDS = ("future_sediment_loss", "future_nutrient_runoff",
           "critical_drinking_water", "high_quality_waters",
           "current_nutrient_export", "current_sediment_export",
           "combined_pollutant_export")

def selected_models(value=None):
    """Return selected native models in their stable execution order.

    An omitted selection preserves the original combined NDR/SDR behavior.
    The explicit selection is carried by a profile, grid or run's models field.
    """
    values = value.get("models", MODELS) if isinstance(value, dict) else value
    if values is None and value is None:
        values = MODELS
    if not isinstance(values, (list, tuple)) or not values:
        raise ValueError("Select a nonempty list of native models: ndr, sdr")
    if any(not isinstance(name, str) for name in values):
        raise ValueError("Native model names must be ndr or sdr")
    names = [name.strip().lower() for name in values]
    if len(names) != len(set(names)) or set(names) - set(MODELS):
        raise ValueError("Select each native model once from ndr, sdr")
    return [name for name in MODELS if name in names]

def required_roles(value=None):
    """Physical inputs required by the selected native models."""
    models = selected_models(value)
    return tuple(role for role in ROLES
                 if any(role in MODEL_ROLES[model] for model in models))

def output_models(value=None):
    """Map actual selected export names to native model/registry identifiers."""
    models = selected_models(value)
    return {name: pair for name, pair in MODEL_OUTPUTS.items() if pair[0] in models}

def now():
    return dt.datetime.now(dt.timezone.utc).isoformat()

def canonical(value):
    return json.dumps(value, sort_keys=True, ensure_ascii=False,
                      separators=(",", ":"), allow_nan=False).encode("utf-8")

def digest(value):
    return hashlib.sha256(canonical(value)).hexdigest()

def file_digest(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for b in iter(lambda: f.read(1024 * 1024), b""):
            h.update(b)
    return h.hexdigest()

def atomic_bytes(path, data, *, immutable=False):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    if immutable and path.exists():
        if path.read_bytes() != data:
            raise ValueError("Immutable project item differs: " + str(path))
        return
    pending = None
    try:
        with tempfile.NamedTemporaryFile(dir=path.parent, prefix=".write-", delete=False) as f:
            pending = Path(f.name)
            f.write(data)
            f.flush()
            os.fsync(f.fileno())
        if immutable:
            try:
                os.link(pending, path)
            except FileExistsError:
                if path.read_bytes() != data:
                    raise ValueError("Concurrent immutable item differs: " + str(path))
            pending.unlink()
            pending = None
        else:
            os.replace(pending, path)
            pending = None
        fd = os.open(path.parent, os.O_RDONLY | os.O_DIRECTORY)
        try:
            os.fsync(fd)
        finally:
            os.close(fd)
    finally:
        if pending is not None:
            pending.unlink(missing_ok=True)

def atomic_json(path, value, *, immutable=False):
    atomic_bytes(path, canonical(value) + b"\n", immutable=immutable)

def read_json(path):
    return json.loads(Path(path).read_text(encoding="utf-8"))

def identifier(value):
    if not isinstance(value, str) or not re.fullmatch(r"[0-9a-f]{64}", value):
        raise ValueError("Select an existing complete project item ID")
    return value

def relative_file(root, value):
    root = Path(root).resolve()
    selected = Path(value)
    if selected.is_absolute() or not selected.parts or ".." in selected.parts:
        raise ValueError("Use a relative file within the selected project")
    p = (root / selected).resolve(strict=True)
    if not p.is_relative_to(root) or not p.is_file():
        raise ValueError("Project member is not a retained regular file")
    return p

def finite(value, name, *, minimum=None, positive=False):
    if isinstance(value, bool):
        raise ValueError(name + " must be numeric")
    result = float(value)
    if not math.isfinite(result):
        raise ValueError(name + " must be finite")
    if minimum is not None and result < minimum or positive and result <= 0:
        raise ValueError(name + " is outside its permitted range")
    return result

@contextlib.contextmanager
def held(path, *, blocking=True):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    fd = os.open(path, os.O_CREAT | os.O_RDWR | os.O_NOFOLLOW, 0o600)
    try:
        fcntl.flock(fd, fcntl.LOCK_EX | (0 if blocking else fcntl.LOCK_NB))
        yield
    finally:
        os.close(fd)

def _file_state(value):
    return (value.st_dev, value.st_ino, value.st_size,
            value.st_mtime_ns, value.st_ctime_ns)

def _sync_directory(path):
    fd = os.open(path, os.O_RDONLY | os.O_DIRECTORY)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)

def _stream_identity(stream, label, *, expected_state=None, output=None):
    before = os.fstat(stream.fileno())
    if not stat.S_ISREG(before.st_mode):
        raise ValueError(label + " is not a regular file")
    state = _file_state(before)
    if expected_state is not None and state != expected_state:
        raise ValueError(label + " changed during intake")
    checksum, size = hashlib.sha256(), 0
    for block in iter(lambda: stream.read(1024 * 1024), b""):
        checksum.update(block)
        if output is not None:
            output.write(block)
        size += len(block)
    if _file_state(os.fstat(stream.fileno())) != state or size != before.st_size:
        raise ValueError(label + " changed during intake")
    return checksum.hexdigest(), size, state

def _retained_object_matches(path, checksum, size, *, verified_state=None):
    try:
        descriptor = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
    except FileNotFoundError:
        return False
    with os.fdopen(descriptor, "rb") as stream:
        opened = os.fstat(stream.fileno())
        if not stat.S_ISREG(opened.st_mode):
            raise ValueError("Retained original object is not a regular file")
        state = _file_state(opened)
        try:
            # Reuse only an identity recorded by this operation, never a bare
            # caller-provided stat tuple. Keep verified_state for API continuity.
            actual, count, state = source_identity(
                stream, path, "Retained original object")
        except (ValueError, FileNotFoundError):
            # A concurrent completed publication or view hard link can change
            # ctime. Recheck under the digest lock before any copy or repair.
            return False
        try:
            current = path.lstat()
        except FileNotFoundError:
            return False
        if _file_state(current) != state or not stat.S_ISREG(current.st_mode):
            return False
        if actual != checksum or count != size:
            return False
        # Complete publication durability even after an interrupted prior intake.
        os.fsync(stream.fileno())
        return True

@verified_operation
def retain_file(project, source, expected_sha256=None):
    """Retain one independent input copy, reusing banked bytes and interrupted intake."""
    source = Path(source).resolve(strict=True)
    if not source.is_file():
        raise ValueError("Source is not a regular file")
    directory = Path(project) / "objects"
    directory.mkdir(parents=True, exist_ok=True)
    expected = identifier(expected_sha256) if expected_sha256 is not None else None
    pending = None
    with source.open("rb") as src:
        if expected is None:
            checksum, size, source_state = source_identity(src, source, "Original input")
            source_verified = True
        else:
            opened = os.fstat(src.fileno())
            if not stat.S_ISREG(opened.st_mode):
                raise ValueError("Original input is not a regular file")
            checksum, size, source_state = expected, opened.st_size, _file_state(opened)
            source_verified = False
        destination = directory / checksum

        def matches():
            return _retained_object_matches(
                destination, checksum, size,
                verified_state=source_state if source_verified else None)

        def reused():
            nonlocal source_verified
            if not source_verified:
                src.seek(0)
                actual, count, _ = source_identity(
                    src, source, "Original input", expected_state=source_state)
                if actual != checksum or count != size:
                    raise ValueError("Original source hash differs: " + source.name)
                source_verified = True
            if _file_state(os.fstat(src.fileno())) != source_state:
                raise ValueError("Original input changed during intake")
            _sync_directory(directory)
            _sync_directory(directory.parent)
            return {"sha256": checksum, "bytes": size,
                    "object": "objects/" + checksum, "filename": source.name}

        # An existing verified object reopens without allocating a lock or a
        # temporary file, including on a full receiving volume.
        if matches():
            return reused()
        with held(directory / (".intake-" + checksum + ".lock")):
            if _file_state(os.fstat(src.fileno())) != source_state:
                raise ValueError("Original input changed during intake")
            if matches():
                return reused()
            try:
                src.seek(0)
                candidate = directory / (".intake-" + checksum + ".partial")
                if candidate.resolve() == source:
                    raise ValueError("Select an original input outside its unfinished intake path")
                # Every retry owns the same digest lock and pending name.
                # Unlink an old alias before creating an independent inode:
                # truncating a prior installed hard link would damage its object.
                candidate.unlink(missing_ok=True)
                descriptor = os.open(candidate, os.O_WRONLY | os.O_CREAT |
                                     os.O_EXCL | os.O_NOFOLLOW, 0o600)
                pending = candidate
                with os.fdopen(descriptor, "wb") as out:
                    copied, copied_size, _ = source_identity(
                        src, source, "Original input", expected_state=source_state, output=out)
                    if copied != checksum or copied_size != size:
                        raise ValueError("Original source hash differs: " + source.name)
                    out.flush()
                    os.fsync(out.fileno())
                if _file_state(os.fstat(src.fileno())) != source_state:
                    raise ValueError("Original input changed during intake")
                try:
                    os.link(pending, destination)
                except FileExistsError:
                    # Preserve a complete concurrent publication or atomically
                    # repair a damaged regular object with this verified copy.
                    if not _retained_object_matches(destination, checksum, size):
                        os.replace(pending, destination)
                        pending = None
                _sync_directory(directory)
                _sync_directory(directory.parent)
            finally:
                if pending is not None:
                    pending.unlink(missing_ok=True)
                    _sync_directory(directory)
    return {"sha256": checksum, "bytes": size, "object": "objects/" + checksum,
            "filename": source.name}

def verify_file(root, item):
    from .verified_files import verify_path
    return verify_path(relative_file(root, item["path"]), item)

def describe_file(root, path, **metadata):
    path = Path(path).resolve(strict=True)
    root = Path(root).resolve()
    if not path.is_relative_to(root):
        raise ValueError("Output is outside the current run")
    return {**metadata, "path": path.relative_to(root).as_posix(),
            "bytes": path.stat().st_size, "sha256": file_digest(path)}

files.model/experiments.py:
"""Source-bound scenario and parameter experiments using original native runs.

A case is one profile/scenario selection. Land-cover effects always use the
baseline scenario under that same profile. Parameter cases use the selected
original baseline as their reference. Completed native runs and case summaries
are reused; a subsequent execute call retries unfinished cases.
"""
from __future__ import annotations

from bisect import bisect_right
import contextlib
import math
import copy
import csv
import hashlib
import io
import itertools
import json

from .common import (INVEST_VERSION, atomic_bytes, atomic_json, canonical,
                     describe_file, digest, held, identifier, now, read_json,
                     verify_file, selected_models, required_roles, output_models)
from .profiles import NDR_KEYS, SDR_KEYS, checked_parameters
from . import rasters
from .native_versions import model_versions, comparison_versions
from .native_execution import storage_exhausted

SELECTION_SCHEMA = "upstate.experiment-selection/v1"
PLAN_SCHEMA = "upstate.experiment-plan/v1"
STATE_SCHEMA = "upstate.experiment/v1"
CASE_SCHEMA = "upstate.experiment-case/v1"
SUMMARY_SCHEMA = "upstate.experiment-summary/v1"

SUPPORTED_AXES = {
    "ndr.threshold_flow_accumulation": {"label": "NDR stream threshold", "units": "upstream cells", "rule": "positive"},
    "ndr.k_param": {"label": "NDR connectivity shape", "units": "dimensionless", "rule": "positive"},
    "ndr.flow_dir_algorithm": {"label": "NDR flow direction", "units": "algorithm", "values": ["mfd", "d8"]},
    "ndr.subsurface_critical_length_n": {"label": "N subsurface critical length", "units": "m", "rule": "positive"},
    "ndr.subsurface_eff_n": {"label": "N subsurface retention efficiency", "units": "fraction", "minimum": 0, "maximum": 1},
    "ndr.runoff_proxy_av": {"label": "NDR runoff-proxy average", "units": "input runoff-proxy units", "rule": "positive or null for native mean"},
    "sdr.threshold_flow_accumulation": {"label": "SDR stream threshold", "units": "upstream cells", "rule": "positive"},
    "sdr.k_param": {"label": "SDR connectivity shape", "units": "dimensionless", "rule": "positive"},
    "sdr.flow_dir_algorithm": {"label": "SDR flow direction", "units": "algorithm", "values": ["mfd", "d8"]},
    "sdr.sdr_max": {"label": "Maximum sediment delivery ratio", "units": "fraction", "minimum": 0, "maximum": 1},
    "sdr.ic_0_param": {"label": "SDR connectivity midpoint", "units": "dimensionless", "rule": "finite"},
    "sdr.l_max": {"label": "Maximum RUSLE L-factor", "units": "dimensionless", "rule": "positive"},
}


def _retain_model_choice(value, models):
    """Match the maintained native selector's historical full-model identity."""
    if list(models) == selected_models():
        value.pop("models", None)
    else:
        value["models"] = list(models)


def _profile_models(profile, models):
    missing = set(models) - set(selected_models(profile))
    if missing:
        raise ValueError("Select a profile containing the reference models: " + ", ".join(sorted(missing)))
    for model in models:
        if not isinstance(profile.get(model), dict):
            raise ValueError("The selected profile lacks its " + model.upper() + " parameters")
    return profile


def supported_axes(models=None):
    """Parameter controls for the selected native model families."""
    families = set(selected_models(models))
    return {path: copy.deepcopy(metadata) for path, metadata in SUPPORTED_AXES.items()
            if path.split(".", 1)[0] in families}


def _nonempty(value, label):
    if not isinstance(value, str) or not value.strip():
        raise ValueError(label + " must be nonempty text")
    return value.strip()


def _ids(value, label):
    if not isinstance(value, list):
        raise ValueError(label + " must be a list")
    result = []
    for item in value:
        item = identifier(item)
        if item not in result:
            result.append(item)
    return result


def _parameter(profile, path):
    model, name = path.split(".", 1)
    return profile[model].get(name)


def _apply(profile, changes):
    value = copy.deepcopy(profile)
    for path, selected in changes.items():
        model, name = path.split(".", 1)
        if selected is None and path == "ndr.runoff_proxy_av":
            value[model].pop(name, None)
        else:
            value[model][name] = selected
    value.update(checked_parameters(value))
    return value



def _source_profile_in_design(workspace, selection, base, profile_id, models):
    """Match one retained source profile without expanding a factorial design."""
    profile = _profile_models(workspace._get("profiles", profile_id), models)
    if profile_id in {base["id"], *selection["profile_ids"]}:
        return True
    axes = selection["axes"]
    overrides = {axis["path"]: _parameter(profile, axis["path"])
                 for axis in axes
                 if _parameter(profile, axis["path"]) != _parameter(base, axis["path"])}
    if not overrides or _derived_profile(base, overrides, axes)["id"] != profile_id:
        return False
    return next(_matching_raw_positions(selection, base, overrides), None) is not None


def _source_binding(run, canonical_selection):
    """Freeze a complete original source under its actual immutable run identity."""
    original = run["selection"]
    if run.get("id") != digest(original):
        raise ValueError("The retained native source selection differs from its run ID")
    if run.get("state") != "complete":
        raise ValueError("Complete a noncanonical original source before adopting it into an experiment")
    models = selected_models(original)
    versions = model_versions(run, models)
    if any(row["comparison_version"] != INVEST_VERSION for row in versions.values()):
        raise ValueError("Every adopted producing model must use the supported native version "
                         + INVEST_VERSION + "; inspect the original completed-stage provenance")
    artifacts = {}
    for name in output_models(models):
        artifact = run.get("artifacts", {}).get(name)
        if (not isinstance(artifact, dict) or not isinstance(artifact.get("path"), str)
                or type(artifact.get("bytes")) is not int or artifact["bytes"] < 1):
            raise ValueError("The completed native source lacks its original " + name + " descriptor")
        identifier(artifact.get("sha256"))
        artifacts[name] = copy.deepcopy(artifact)
    return {
        "schema": "upstate.experiment-native-source/v1",
        "canonical_run_id": digest(canonical_selection),
        "run_id": run["id"], "selection": copy.deepcopy(original),
        "models": list(models),
        "producing_versions": {model: versions[model]["comparison_version"] for model in models},
        "artifacts": artifacts,
    }


def _source_runs(workspace, selection, baseline, base):
    """Resolve explicit source cells once; ordinary canonical identities stay unchanged."""
    models = selected_models(baseline["selection"])
    allowed_scenarios = {baseline["selection"]["scenario_id"], *selection["scenario_ids"]}
    sources = {baseline["id"]: baseline}
    for key in _ids(selection.get("source_run_ids", []), "Original source run IDs"):
        if key not in sources:
            sources[key] = workspace.inspect_run(key)
    seen, retained = {}, []
    for key, run in sources.items():
        original = run["selection"]
        if (digest(original) != key
                or original["grid_id"] != baseline["selection"]["grid_id"]
                or selected_models(original) != models
                or original["scenario_id"] not in allowed_scenarios
                or not _source_profile_in_design(
                    workspace, selection, base, original["profile_id"], models)):
            raise ValueError("An original source run is outside the selected experiment's grid, models or cases: " + key)
        canonical_selection = _run_selection(
            original["grid_id"], original["profile_id"], original["scenario_id"], models)
        canonical_id = digest(canonical_selection)
        if canonical_id in seen and seen[canonical_id] != key:
            raise ValueError("Choose one original native source for each experiment profile/scenario case")
        seen[canonical_id] = key
        if key != canonical_id:
            retained.append(_source_binding(run, canonical_selection))
    return sorted(retained, key=lambda row: row["canonical_run_id"])


def _validate_sources(workspace, plan):
    """Reopen the exact saved originals without changing a retained plan or source."""
    selected = plan["selection"]
    retained = plan.get("source_runs", [])
    if not retained and "source_run_ids" not in selected:
        return
    baseline = workspace.inspect_run(plan["baseline"]["run_id"])
    base = workspace._get("profiles", plan["baseline"]["profile_id"])
    actual = _source_runs(workspace, selected, baseline, base)
    if (not retained or actual != retained
            or selected.get("source_run_ids") != sorted(row["run_id"] for row in actual)):
        raise ValueError("The experiment's frozen original source bindings differ from the retained runs")


def _adopted_selection(plan, canonical_selection):
    key = digest(canonical_selection)
    for source in plan.get("source_runs", []):
        if source["canonical_run_id"] == key:
            return copy.deepcopy(source["selection"]), copy.deepcopy(source)
    return canonical_selection, None


def _normalise(workspace, selected):
    if not isinstance(selected, dict):
        raise ValueError("Supply an experiment selection object")
    unknown = set(selected) - {"schema", "title", "reason", "baseline_run_id",
                               "scenario_ids", "profile_ids", "design", "axes", "source_run_ids"}
    if unknown:
        raise ValueError("Unknown experiment fields: " + ", ".join(sorted(unknown)))
    if selected.get("schema", SELECTION_SCHEMA) != SELECTION_SCHEMA:
        raise ValueError("Select an upstate.experiment-selection/v1 document")
    baseline = workspace.inspect_run(identifier(selected.get("baseline_run_id")))
    base_selection = baseline["selection"]
    models = selected_models(base_selection)
    if base_selection.get("invest_version") != INVEST_VERSION:
        _source_binding(baseline, _run_selection(
            base_selection["grid_id"], base_selection["profile_id"],
            base_selection["scenario_id"], models))
    grid = workspace.get_grid(base_selection["grid_id"])
    if not set(models).issubset(selected_models(grid["spec"])):
        raise ValueError("The reference run selects native models outside its retained grid")
    missing_roles = set(required_roles(models)) - set(grid["files"])
    if missing_roles:
        raise ValueError("The reference grid lacks selected model inputs: " + ", ".join(sorted(missing_roles)))
    base_profile = workspace._get("profiles", base_selection["profile_id"])
    _profile_models(base_profile, models)
    base_scenario = workspace._get("scenarios", base_selection["scenario_id"])
    if base_scenario["kind"] != "baseline":
        raise ValueError("The experiment reference must use the original land-cover baseline")
    scenario_ids = _ids(selected.get("scenario_ids", []), "Scenario IDs")
    for key in scenario_ids:
        value = workspace._get("scenarios", key)
        if value["kind"] != "landcover":
            raise ValueError("Experiment alternatives must be explicit retained land-cover scenarios")
    profile_ids = _ids(selected.get("profile_ids", []), "Profile IDs")
    profile_ids = [key for key in profile_ids if key != base_profile["id"]]
    for key in profile_ids:
        _profile_models(workspace._get("profiles", key), models)
    design = selected.get("design", "one_at_a_time")
    if design not in ("one_at_a_time", "factorial"):
        raise ValueError("Experiment design must be one_at_a_time or factorial")
    axes = selected.get("axes", [])
    if not isinstance(axes, list):
        raise ValueError("Parameter axes must be a list")
    normal_axes, seen = [], set()
    for axis in axes:
        if not isinstance(axis, dict) or set(axis) != {"path", "values", "reference"}:
            raise ValueError("Each parameter axis needs path, values and reference")
        path = axis["path"]
        if not isinstance(path, str) or path not in SUPPORTED_AXES:
            raise ValueError("Select an existing NDR or SDR native parameter")
        if path.split(".", 1)[0] not in models:
            raise ValueError(path + " does not belong to the reference run's selected models")
        if path in seen:
            raise ValueError("Parameter axes must have distinct paths")
        seen.add(path)
        reference = _nonempty(axis["reference"], "Parameter source or scientific rationale")
        if not isinstance(axis["values"], list) or not axis["values"]:
            raise ValueError("Supply explicit values for " + path)
        values, tokens = [], set()
        for raw in axis["values"]:
            value = _parameter(_apply(base_profile, {path: raw}), path)
            # Signed zeros select the same native value; retain their first spelling.
            token = canonical(0.0 if isinstance(value, float) and value == 0 else value)
            if token not in tokens:
                values.append(value)
                tokens.add(token)
        normal_axes.append({"path": path, "values": values, "reference": reference})
    normal_axes.sort(key=lambda item: item["path"])
    selection = {
        "schema": SELECTION_SCHEMA,
        "title": _nonempty(selected.get("title"), "Experiment title"),
        "reason": _nonempty(selected.get("reason"), "Experiment purpose"),
        "baseline_run_id": baseline["id"], "scenario_ids": scenario_ids,
        "profile_ids": profile_ids, "design": design, "axes": normal_axes,
    }
    requested_sources = _ids(selected.get("source_run_ids", []), "Original source run IDs")
    if requested_sources:
        selection["source_run_ids"] = requested_sources
    sources = _source_runs(workspace, selection, baseline, base_profile)
    if sources:
        selection["source_run_ids"] = sorted(row["run_id"] for row in sources)
    else:
        selection.pop("source_run_ids", None)
    # This also rejects nonfinite values in retained metadata before publication.
    canonical(selection)
    return selection, baseline, base_profile, base_scenario


def _changes(base, alternative, models=None):
    result = []
    families = set(selected_models(models))
    for model, names in (("ndr", NDR_KEYS), ("sdr", SDR_KEYS)):
        if model not in families:
            continue
        for name in sorted(names):
            before, after = base.get(model, {}).get(name), alternative.get(model, {}).get(name)
            if before != after:
                result.append({"path": model + "." + name, "before": before, "value": after})
    if base["table_summary"]["sha256"] != alternative["table_summary"]["sha256"]:
        result.append({"path": "biophysical_table_sha256",
                       "before": base["table_summary"]["sha256"],
                       "value": alternative["table_summary"]["sha256"]})
    return result


def _parameter_sets(selection, base):
    axes = selection["axes"]
    if not axes:
        return
    if selection["design"] == "one_at_a_time":
        for axis in axes:
            for value in axis["values"]:
                if value != _parameter(base, axis["path"]):
                    yield {axis["path"]: value}
    else:
        paths = [axis["path"] for axis in axes]
        for combination in itertools.product(*(axis["values"] for axis in axes)):
            changes = {path: value for path, value in zip(paths, combination)
                       if value != _parameter(base, path)}
            if changes:
                yield changes


def _derived_profile(base, overrides, axes):
    value = _apply(base, overrides)
    for name in ("id", "schema"):
        value.pop(name, None)
    labels = [path + "=" + json.dumps(selected, ensure_ascii=False)
              for path, selected in sorted(overrides.items())]
    value["title"] = base["title"] + " / " + "; ".join(labels)
    selected_axes = {axis["path"]: axis for axis in axes}
    references = copy.deepcopy(base["references"])
    if not isinstance(references, list):
        references = [references]
    derivation = []
    for path, selected in sorted(overrides.items()):
        reference = selected_axes[path]["reference"]
        if reference not in references:
            references.append(reference)
        derivation.append({"path": path, "before": _parameter(base, path),
                           "value": selected, "reference": reference})
    value["references"] = references
    value["experiment_derivation"] = {"base_profile_id": base["id"],
                                      "parameters": derivation}
    key = digest({**value, "schema": "upstate.profiles/v1"})
    return {"id": key, "profile": value, "derived": True, "changes": derivation}


def _profiles(workspace, selection, base, models=None):
    # Normalized axis values are unique. OAT choices and factorial combinations
    # therefore yield unique derived selections without retaining the matrix.
    retained_ids = {base["id"], *selection["profile_ids"]}
    yield {"id": base["id"], "profile": base, "derived": False, "changes": []}
    for key in selection["profile_ids"]:
        profile = workspace._get("profiles", key)
        yield {"id": key, "profile": profile, "derived": False,
               "changes": _changes(base, profile, models)}
    for overrides in _parameter_sets(selection, base):
        option = _derived_profile(base, overrides, selection["axes"])
        if option["id"] not in retained_ids:
            yield option



def _matching_raw_positions(selection, base, overrides):
    """Positions that yield these exact overrides in the original generator."""
    axes = selection["axes"]
    if not axes:
        return
    if selection["design"] == "one_at_a_time":
        offset = 0
        if len(overrides) > 1:
            return
        for axis in axes:
            path = axis["path"]
            if not overrides:
                for index, value in enumerate(axis["values"]):
                    if value == _parameter(base, path):
                        yield offset + index
            elif path in overrides:
                token = canonical(overrides[path])
                for index, value in enumerate(axis["values"]):
                    if canonical(value) == token:
                        yield offset + index
            offset += len(axis["values"])
        return
    choices = []
    for axis in axes:
        path = axis["path"]
        if path in overrides:
            token = canonical(overrides[path])
            indexes = [i for i, value in enumerate(axis["values"]) if canonical(value) == token]
        else:
            indexes = [i for i, value in enumerate(axis["values"])
                       if value == _parameter(base, path)]
        if not indexes:
            return
        choices.append(indexes)
    # These are matching positions, not the full design product. In particular,
    # signed-zero aliases of unchanged values retain their original positions.
    for selected in itertools.product(*choices):
        position = 0
        for index, axis in zip(selected, axes):
            position = position * len(axis["values"]) + index
        yield position


def _indexed_design(workspace, selection, base, models=None):
    """Count a design and locate profile ordinals without expanding its matrix."""
    retained = [{"id": base["id"], "profile": base, "derived": False, "changes": []}]
    for key in selection["profile_ids"]:
        profile = workspace._get("profiles", key)
        retained.append({"id": key, "profile": profile, "derived": False,
                         "changes": _changes(base, profile, models)})
    axes = selection["axes"]
    if selection["design"] == "one_at_a_time":
        raw_count = sum(len(axis["values"]) for axis in axes)
    else:
        raw_count = 1 if axes else 0
        for axis in axes:
            raw_count *= len(axis["values"])
    excluded = set(_matching_raw_positions(selection, base, {}))
    for option in retained[1:]:
        # Matching fields alone do not establish profile identity. Reconstruct
        # the exact existing title/references/table lineage and match its digest.
        overrides = {axis["path"]: _parameter(option["profile"], axis["path"])
                     for axis in axes
                     if _parameter(option["profile"], axis["path"]) != _parameter(base, axis["path"])}
        if not overrides:
            continue
        if selection["design"] == "one_at_a_time" and len(overrides) != 1:
            continue
        candidate = _derived_profile(base, overrides, axes)
        if candidate["id"] != option["id"]:
            continue
        excluded.update(_matching_raw_positions(selection, base, overrides))
    excluded = sorted(excluded)
    return {"retained": retained, "excluded": excluded, "raw_count": raw_count,
            "count": len(retained) + raw_count - len(excluded),
            "selection": selection, "base": base}


def _surviving_raw_position(index, excluded):
    """Select a raw position by rank among positions outside a sparse set."""
    low, high = index, index + len(excluded)
    while low < high:
        middle = (low + high) // 2
        through = middle + 1 - bisect_right(excluded, middle)
        if through > index:
            high = middle
        else:
            low = middle + 1
    return low


def _indexed_profile(layout, index):
    if index < 0 or index >= layout["count"]:
        raise IndexError("Experiment profile index is outside the selected design")
    retained = layout["retained"]
    if index < len(retained):
        return retained[index]
    position = _surviving_raw_position(index - len(retained), layout["excluded"])
    selection, base = layout["selection"], layout["base"]
    axes = selection["axes"]
    if selection["design"] == "one_at_a_time":
        for axis in axes:
            if position < len(axis["values"]):
                overrides = {axis["path"]: axis["values"][position]}
                break
            position -= len(axis["values"])
        else:
            raise ValueError("Experiment index differs from its selected axes")
    else:
        overrides = {}
        for axis in reversed(axes):
            position, level = divmod(position, len(axis["values"]))
            value = axis["values"][level]
            if value != _parameter(base, axis["path"]):
                overrides[axis["path"]] = value
    return _derived_profile(base, overrides, axes)


def preview(workspace, selection):
    selection, baseline, base, _ = _normalise(workspace, selection)
    models = selected_models(baseline["selection"])
    profile_count = _indexed_design(workspace, selection, base, models)["count"]
    case_count = profile_count * (1 + len(selection["scenario_ids"]))
    warnings = []
    if selection["design"] == "one_at_a_time" and len(selection["axes"]) > 1:
        warnings.append("One-at-a-time results describe individual parameter changes; interactions require a factorial design.")
    if not selection["axes"] and not selection["profile_ids"] and not selection["scenario_ids"]:
        warnings.append("This selection contains the reference baseline only.")
    for axis in selection["axes"]:
        if all(value == _parameter(base, axis["path"]) for value in axis["values"]):
            warnings.append(axis["path"] + " contains only the current value and creates no additional profile.")
    reference = {"run_id": baseline["id"], "profile_id": base["id"],
                 "scenario_id": baseline["selection"]["scenario_id"],
                 "grid_id": baseline["selection"]["grid_id"]}
    _retain_model_choice(reference, models)
    sources = _source_runs(workspace, selection, baseline, base)
    return {
        **({"source_runs": sources} if sources else {}),
        "schema": "upstate.experiment-preview/v1", "selection": selection,
        "baseline": reference, "models": list(models),
        "pollutants": list(output_models(models)),
        "counts": {"profiles": profile_count, "runs": case_count, "cases": case_count},
        "axis_values": [{**axis, "baseline_value": _parameter(base, axis["path"]),
                         "metadata": copy.deepcopy(SUPPORTED_AXES[axis["path"]])}
                        for axis in selection["axes"]],
        "warnings": warnings,
    }


def _directory(workspace, key):
    return workspace.root / "experiments" / identifier(key)


def _plan(workspace, key):
    directory = _directory(workspace, key)
    plan = read_json(directory / "plan.json")
    if (plan.get("schema") != PLAN_SCHEMA or digest(plan) != key
            or plan.get("workspace_id") != workspace.project["id"]):
        raise ValueError("The experiment selection differs from the retained workspace")
    reference = workspace.inspect_run(plan["baseline"]["run_id"])
    selected = reference["selection"]
    if (any(selected[name] != plan["baseline"][name]
            for name in ("grid_id", "profile_id", "scenario_id"))
            or (selected.get("invest_version") != INVEST_VERSION
                and reference["id"] not in plan["selection"].get("source_run_ids", []))):
        raise ValueError("The experiment reference differs from its retained native selection")
    _validate_sources(workspace, plan)
    active = selected_models(selected)
    if ("models" in plan["baseline"]
            and selected_models(plan["baseline"]) != active):
        raise ValueError("The experiment reference native models differ from its retained selection")
    if active != ["ndr", "sdr"]:
        # Recover old partial-model plans in memory while retaining their
        # immutable original plan bytes, experiment ID, and generated case IDs.
        plan["_legacy_case_ids"] = "models" not in plan["baseline"]
        plan["baseline"] = {**plan["baseline"], "models": active}
    return plan


def _state(workspace, key):
    value = read_json(_directory(workspace, key) / "state.json")
    return _check_state(workspace, key, value)


def _check_state(workspace, key, value):
    """Use the same original checkpoint identity in full and catalogue reads."""
    if (value.get("schema") != STATE_SCHEMA or value.get("id") != key
            or value.get("workspace_id") != workspace.project["id"]):
        raise ValueError("The retained experiment state belongs to another selection")
    return value


def prepare(workspace, selection):
    proposed = preview(workspace, selection)
    plan = {"schema": PLAN_SCHEMA, "workspace_id": workspace.project["id"],
            "selection": proposed["selection"], "baseline": proposed["baseline"],
            "counts": proposed["counts"]}
    if proposed.get("source_runs"):
        plan["source_runs"] = proposed["source_runs"]
    key = digest(plan)
    directory = _directory(workspace, key)
    directory.mkdir(parents=True, exist_ok=True)
    with held(directory / ".experiment.lock", blocking=False):
        atomic_json(directory / "plan.json", plan, immutable=True)
        path = directory / "state.json"
        if path.exists():
            return _state(workspace, key)
        created = now()
        value = {
            "schema": STATE_SCHEMA, "id": key, "workspace_id": workspace.project["id"],
            "title": plan["selection"]["title"], "selection": plan["selection"],
            "models": proposed["models"], "pollutants": proposed["pollutants"],
            "counts": plan["counts"], "state": "prepared",
            "progress": {"complete": 0, "failed": 0, "pending": plan["counts"]["cases"],
                         "active_case_id": None},
            "created_at": created, "updated_at": created, "files": {},
        }
        atomic_json(path, value)
        return value


def _run_selection(grid_id, profile_id, scenario_id, models=None):
    value = {"schema": "upstate.run-selection/v1", "grid_id": grid_id,
             "profile_id": profile_id, "scenario_id": scenario_id,
             "invest_version": INVEST_VERSION}
    _retain_model_choice(value, selected_models(models))
    return value


def _case_definition(plan, option, scenario, ordinal):
    baseline = plan["baseline"]
    models = selected_models(baseline)
    baseline_selection, baseline_source = _adopted_selection(plan, _run_selection(
        baseline["grid_id"], option["id"], baseline["scenario_id"], models))
    own_baseline = digest(baseline_selection)
    is_baseline = scenario["id"] == baseline["scenario_id"]
    kind = ("reference" if option["id"] == baseline["profile_id"] else "parameter") if is_baseline else "landcover"
    run_selection, native_source = _adopted_selection(
        plan, _run_selection(baseline["grid_id"], option["id"], scenario["id"], models))
    run_id = digest(run_selection)
    paired_baseline = baseline["run_id"] if is_baseline else own_baseline
    if is_baseline:
        baseline_source = next((copy.deepcopy(row) for row in plan.get("source_runs", [])
                                if row["run_id"] == paired_baseline), None)
    adopted = {}
    if native_source is not None:
        adopted["native_source"] = native_source
    if baseline_source is not None:
        adopted["native_baseline_source"] = baseline_source
    identity = {"run_id": run_id, "baseline_run_id": paired_baseline, "kind": kind}
    original = {}
    case_identity = identity
    if plan.get("_legacy_case_ids"):
        source_selection = _run_selection(baseline["grid_id"], option["id"], scenario["id"])
        source_baseline = (baseline["run_id"] if is_baseline else digest(_run_selection(
            baseline["grid_id"], option["id"], baseline["scenario_id"])))
        case_identity = {"run_id": digest(source_selection),
                         "baseline_run_id": source_baseline, "kind": kind}
        original = {"source_run_id": case_identity["run_id"],
                    "source_baseline_run_id": source_baseline,
                    "source_selection": source_selection}
    return {
        "schema": CASE_SCHEMA, "id": digest(case_identity), "ordinal": ordinal,
        **identity, **original, **adopted, "profile_id": option["id"], "profile_title": option["profile"]["title"],
        "scenario_id": scenario["id"], "scenario_title": scenario["title"],
        "selection": run_selection, "models": list(models),
        "pollutants": list(output_models(models)), "state": "pending", "changes": option["changes"],
        "metrics": {}, "comparison_id": None,
    }


def _case_definitions(workspace, plan):
    selection, baseline = plan["selection"], plan["baseline"]
    base = workspace._get("profiles", baseline["profile_id"])
    scenarios = [workspace._get("scenarios", baseline["scenario_id"])]
    scenarios += [workspace._get("scenarios", key) for key in selection["scenario_ids"]]
    ordinal = 0
    for option in _profiles(workspace, selection, base, selected_models(baseline)):
        for scenario in scenarios:
            yield _case_definition(plan, option, scenario, ordinal), option
            ordinal += 1


def _retained_case(directory, expected):
    path = directory / "cases" / (expected["id"] + ".json")
    if not path.exists():
        return expected
    value = read_json(path)
    fields = ("schema", "id", "run_id", "baseline_run_id", "kind", "profile_id",
              "scenario_id", "selection", "ordinal")
    if all(value.get(field) == expected[field] for field in fields):
        if any(value.get(field) != expected.get(field)
               for field in ("native_source", "native_baseline_source")):
            raise ValueError("The retained experiment case changed its frozen native source")
        return {**expected, **value}
    if "source_selection" in expected:
        original = {**expected, "run_id": expected["source_run_id"],
                    "baseline_run_id": expected["source_baseline_run_id"],
                    "selection": expected["source_selection"]}
        if all(value.get(field) == original[field] for field in fields):
            # Prior metrics belong to the old native selection. Preserve that
            # record and collect fresh metrics from the canonical native run.
            return {**expected, "previous_case": value, "_binding_recovery": True}
    raise ValueError("The retained experiment case changed: " + expected["id"])


def _persist_case(directory, case):
    atomic_json(directory / "cases" / (case["id"] + ".json"), case)


def _progress(directory, state, *, active=None):
    complete = failed = 0
    for path in (directory / "cases").glob("*.json"):
        value = read_json(path)
        complete += value.get("state") == "complete"
        failed += value.get("state") == "failed"
    state["progress"] = {"complete": complete, "failed": failed,
                         "pending": max(0, state["counts"]["cases"] - complete - failed),
                         "active_case_id": active}
    state["updated_at"] = now()
    atomic_json(directory / "state.json", state)
    return state


def _recover_case_bindings(workspace, plan, directory, state):
    active = selected_models(plan["baseline"])
    if not plan.get("_legacy_case_ids") or state.get("native_binding_models") == active:
        return state
    # Seek only retained case ordinals. An old sparse factorial programme must
    # not expand its unmaterialized matrix merely to recover native bindings.
    records = []
    seen = set()
    for path in (directory / "cases").glob("*.json"):
        ordinal = read_json(path).get("ordinal")
        if (type(ordinal) is not int or ordinal < 0
                or ordinal >= plan["counts"]["cases"] or ordinal in seen):
            raise ValueError("The retained experiment case index differs from its plan")
        seen.add(ordinal)
        records.append((ordinal, path))
    if records:
        base = workspace._get("profiles", plan["baseline"]["profile_id"])
        layout = _indexed_design(workspace, plan["selection"], base, active)
        scenario_ids = [plan["baseline"]["scenario_id"]] + plan["selection"]["scenario_ids"]
        if layout["count"] * len(scenario_ids) != plan["counts"]["cases"]:
            raise ValueError("The indexed design differs from the retained experiment case count")
        previous_profile, option, scenarios = None, None, {}
        for ordinal, path in sorted(records, key=lambda item: item[0]):
            profile_index, scenario_index = divmod(ordinal, len(scenario_ids))
            if profile_index != previous_profile:
                option = _indexed_profile(layout, profile_index)
                previous_profile = profile_index
            scenario_id = scenario_ids[scenario_index]
            if scenario_id not in scenarios:
                scenarios[scenario_id] = workspace._get("scenarios", scenario_id)
            expected = _case_definition(plan, option, scenarios[scenario_id], ordinal)
            if expected["id"] != path.stem:
                raise ValueError("The retained case file differs from its experiment ordinal")
            case = _retained_case(directory, expected)
            if case.pop("_binding_recovery", False):
                case["binding_recovered_at"] = now()
                _persist_case(directory, case)
    state.update(native_binding_models=active, models=list(active),
                 pollutants=list(output_models(active)), bindings_recovered_at=now())
    # Previous summaries describe the old model bindings. Keep their files,
    # and advertise a new summary after the recovered cases are summarized.
    state.pop("summary_at", None)
    state["files"] = {}
    state = _progress(directory, state)
    if state["progress"]["complete"] != plan["counts"]["cases"]:
        state["state"] = ("partial" if state["progress"]["complete"] else
                          "failed" if state["progress"]["failed"] else "prepared")
        state.pop("completed_at", None)
        state.pop("error", None)
        atomic_json(directory / "state.json", state)
    return state


def list_experiments(workspace):
    result = []
    for path in sorted((workspace.root / "experiments").glob("*/state.json")):
        value = _state(workspace, path.parent.name)
        result.append(value)
    return sorted(result, key=lambda item: (item["updated_at"], item["id"]), reverse=True)


def _indexed_case_definitions(workspace, plan, offset, limit):
    """Select case ordinals without deriving any preceding profile."""
    total = plan["counts"]["cases"]
    if offset >= total:
        return
    base = workspace._get("profiles", plan["baseline"]["profile_id"])
    layout = _indexed_design(workspace, plan["selection"], base, selected_models(plan["baseline"]))
    scenario_ids = [plan["baseline"]["scenario_id"]] + plan["selection"]["scenario_ids"]
    scenario_count = len(scenario_ids)
    if layout["count"] * scenario_count != total:
        raise ValueError("The selected experiment index differs from its retained case count")
    stop = total if limit is None else min(total, offset + limit)
    scenario_cache, previous_profile, option = {}, None, None
    for ordinal in range(offset, stop):
        profile_index, scenario_index = divmod(ordinal, scenario_count)
        if profile_index != previous_profile:
            option = _indexed_profile(layout, profile_index)
            previous_profile = profile_index
        scenario_id = scenario_ids[scenario_index]
        if scenario_id not in scenario_cache:
            scenario_cache[scenario_id] = workspace._get("scenarios", scenario_id)
        yield _case_definition(plan, option, scenario_cache[scenario_id], ordinal), option


def _case_window(offset, limit, *, unlimited=False):
    if type(offset) is not int or offset < 0:
        raise ValueError("Use a nonnegative integer case offset")
    if limit is None and unlimited:
        return
    if type(limit) is not int or limit <= 0:
        raise ValueError("Use a positive integer page size")


def inspect(workspace, experiment_id, offset=0, limit=100):
    _case_window(offset, limit)
    plan = _plan(workspace, experiment_id)
    state = _state(workspace, experiment_id)
    directory = _directory(workspace, experiment_id)
    total = plan["counts"]["cases"]
    cases = [_retained_case(directory, case)
             for case, _ in _indexed_case_definitions(workspace, plan, offset, limit)]
    next_offset = offset + len(cases)
    models = selected_models(plan["baseline"])
    return {**state, "models": list(models), "pollutants": list(output_models(models)),
            "cases": cases, "offset": offset, "limit": limit,
            "total_cases": total, "next_offset": next_offset if next_offset < total else None}


def expanded_cases(workspace, experiment_id, offset=0, limit=100):
    """Read the exact indexed case page for native programme composition."""
    return inspect(workspace, experiment_id, offset=offset, limit=limit)


def _prepare_case_run(workspace, case, option):
    if case.get("native_source") is not None:
        run = workspace.inspect_run(case["run_id"])
        selected = run["selection"]
        canonical_selection = _run_selection(selected["grid_id"], selected["profile_id"],
                                             selected["scenario_id"], selected_models(selected))
        if (_source_binding(run, canonical_selection) != case["native_source"]
                or selected != case["selection"]):
            raise ValueError("The adopted original native run differs from its saved experiment case")
        return run
    if option["derived"]:
        path = workspace.root / "profiles" / (option["id"] + ".json")
        profile = (workspace._get("profiles", option["id"]) if path.exists()
                   else workspace.save_profile(option["profile"]))
        if profile["id"] != option["id"]:
            raise ValueError("Derived native profile differs from the planned selection")
    run = workspace.prepare_run(case["selection"])
    if run["id"] != case["run_id"]:
        raise ValueError("Prepared native run differs from the experiment case")
    return run


def materialize_cases(workspace, experiment_id, offset=0, limit=None):
    """Yield prepared cases in their exact order, without executing native work.

    This is a streaming iterator. Consume it to retain the selected derived
    profiles and original native run selections. An optional window jumps
    directly to its first ordinal. Completed experiment results stay intact;
    resuming this iterator reuses the already retained profiles and runs.
    """
    _case_window(offset, limit, unlimited=True)
    plan = _plan(workspace, experiment_id)
    directory = _directory(workspace, experiment_id)
    if plan.get("_legacy_case_ids"):
        with held(directory / ".experiment.lock", blocking=False):
            _recover_case_bindings(workspace, plan, directory, _state(workspace, experiment_id))
    for expected, option in _indexed_case_definitions(workspace, plan, offset, limit):
        with held(directory / ".experiment.lock", blocking=False):
            case = _retained_case(directory, expected)
            run = _prepare_case_run(workspace, case, option)
            if case["state"] != "complete":
                case.update(native_state=run["state"], materialized_at=case.get("materialized_at") or now())
                _persist_case(directory, case)
        yield {**case, "native_state": run["state"]}

def _reporting_cells(workspace, grid_id):
    import numpy as np
    import rasterio
    grid = workspace.get_grid(grid_id)
    path = verify_file(workspace.root / "grids" / grid_id, grid["files"]["reporting_mask"])
    count = 0
    with rasterio.open(path) as source:
        for _, window in source.block_windows(1):
            count += int(np.count_nonzero(source.read(1, window=window) == 1))
    if not count:
        raise ValueError("The selected reporting mask contains no cells")
    return count, grid["grid"]["pixel_area_ha"]


AREA_METRICS_SCHEMA = "upstate.experiment-per-area/v1"
_AREA_FIELDS = {
    "nitrogen_export": ("load_n", "load_type_n", "eff_n", "crit_len_n", "proportion_subsurface_n"),
    "phosphorus_export": ("load_p", "load_type_p", "eff_p", "crit_len_p"),
    "sediment_export": ("usle_c", "usle_p"),
}


def _area_ratio(value, area):
    return value / area if value is not None and area > 0 else None


def _area_source_context(workspace, baseline, alternative):
    """Read completed native inputs; never compile a new footprint or run a model."""
    from .profiles import inspect_table
    grid_id = baseline["selection"]["grid_id"]
    if alternative["selection"]["grid_id"] != grid_id:
        raise ValueError("Per-area responses require the original common model grid")
    grid = workspace.get_grid(grid_id)
    directory = workspace.root / "grids" / grid_id
    reporting = verify_file(directory, grid["files"]["reporting_mask"])
    domain = verify_file(directory, grid["files"]["model_domain"])
    sides = []
    missing = []
    for run in (baseline, alternative):
        selected = run["selection"]
        profile = workspace._get("profiles", selected["profile_id"])
        scenario = workspace._get("scenarios", selected["scenario_id"])
        table, entry = workspace.source_file(profile["source_collection_id"], profile["biophysical_source_id"])
        if entry["body"]["sha256"] != profile["table_summary"]["sha256"]:
            raise ValueError("The original profile's coefficient table has changed")
        rows = inspect_table(table, selected_models=selected_models(selected))["rows"]
        if scenario["kind"] == "baseline":
            descriptor = grid["files"]["NLCD"]
            landcover = verify_file(directory, descriptor)
        else:
            descriptor = run.get("stages", {}).get("landcover", {}).get("artifact")
            if descriptor is None:
                missing.append(run["id"])
                landcover = None
            else:
                landcover = verify_file(workspace.root / "runs" / run["id"], descriptor)
        sides.append({
            "profile": profile, "rows": {int(row["lucode"]): row for row in rows},
            "landcover": landcover,
            "source": {"run_id": run["id"], "profile_id": profile["id"],
                       "scenario_id": scenario["id"], "landcover": copy.deepcopy(descriptor),
                       "table": {"source_collection_id": profile["source_collection_id"],
                                 "source_id": profile["biophysical_source_id"],
                                 "body": copy.deepcopy(entry["body"]),
                                 **{key: entry[key] for key in ("title", "uri", "vintage") if key in entry}}},
        })
    return {"grid": grid, "reporting_path": reporting, "domain_path": domain, "sides": sides,
            "unavailable": ("The completed land-cover raster descriptor is absent for run(s): "
                            + ", ".join(missing)) if missing else None}


def _area_table_changes(context, pollutant):
    """Compare actual native values, including load type, without relying on profile labels."""
    sides = context["sides"]
    fields = _AREA_FIELDS[pollutant]
    rows = [side["rows"] for side in sides]
    changed_codes, changes = set(), []
    for code in sorted(set(rows[0]) | set(rows[1])):
        for field in fields:
            original = [table.get(code, {}).get(field) for table in rows]
            values = [None if value is None else value.strip() if field.startswith("load_type_")
                      else float(value) for value in original]
            if values[0] != values[1]:
                changed_codes.add(code)
                changes.append({"lucode": code, "field": field,
                                "before": values[0], "after": values[1],
                                "before_original_text": original[0], "after_original_text": original[1]})
    model = "sdr" if pollutant == "sediment_export" else "ndr"
    names = SDR_KEYS if model == "sdr" else NDR_KEYS
    if pollutant == "phosphorus_export":
        names = names - {"subsurface_critical_length_n", "subsurface_eff_n"}
    global_changes = []
    for name in sorted(names):
        before = sides[0]["profile"][model].get(name)
        after = sides[1]["profile"][model].get(name)
        if before != after:
            global_changes.append({"path": model + "." + name, "before": before, "after": after})
    return changed_codes, changes, global_changes


def _area_result(metric, pollutant, context, counts, changed_totals, changes,
                 global_changes, footprint_sha256):
    """Keep whole-reporting response distinct from density on changed cells."""
    area = float(context["grid"]["grid"]["pixel_area_ha"])
    paired_area = metric["paired_area_ha"]
    density = {name: _area_ratio(metric[name], paired_area)
               for name in ("baseline_total", "alternative_total", "delta", "reduction")}
    result = {"schema": AREA_METRICS_SCHEMA, "units": rasters.RATE_UNITS[pollutant],
              "paired_reporting": {"area_ha": paired_area, **density},
              "status": "input_footprint_unavailable" if context["unavailable"] else "available"}
    if context["unavailable"]:
        result["reason"] = context["unavailable"]
        return result
    changed_area = counts["changed_cells"] * area
    local_area = counts["paired_changed_cells"] * area
    local_delta = changed_totals[1] - changed_totals[0] if local_area else None
    attributable = (not global_changes and not counts["landcover_support_changed_cells"]
                    and changed_area > 0 and metric["paired_cells"] > 0)
    reason = ("Global model parameters also changed; the total response is not attributed to the spatial input change."
              if global_changes else "Land-cover valid support differs between the original inputs."
              if counts["landcover_support_changed_cells"] else "No actual changed-input area on the model domain."
              if not changed_area else "No paired-valid reported output cells."
              if not metric["paired_cells"] else None)
    result.update(
        input_footprint={
            "basis": "model-domain pixel centres with valid original land cover in both runs",
            "definition": "Actual land-cover code differences, plus changed pollutant-relevant coefficient values where the retained class is unchanged; each cell counts once.",
            **counts, "area_ha": changed_area,
            "domain_valid_area_ha": counts["domain_valid_cells"] * area,
            "reporting_area_ha": counts["reporting_changed_cells"] * area,
            "paired_area_ha": local_area,
            "paired_fraction_of_reporting_changed": (
                counts["paired_changed_cells"] / counts["reporting_changed_cells"]
                if counts["reporting_changed_cells"] else None),
            "sha256": footprint_sha256, "coefficient_changes": changes,
            "global_parameter_changes": global_changes,
            "sources": {"baseline": context["sides"][0]["source"],
                        "alternative": context["sides"][1]["source"],
                        "model_domain": copy.deepcopy(context["grid"]["files"]["model_domain"]),
                        "reporting_mask": copy.deepcopy(context["grid"]["files"]["reporting_mask"])}},
        whole_reporting_response_per_changed_ha={
            "delta": _area_ratio(metric["delta"], changed_area) if attributable else None,
            "reduction": _area_ratio(metric["reduction"], changed_area) if attributable else None,
            "denominator_area_ha": changed_area, "available": attributable, "reason": reason,
            "numerator": "Total annual mass change over all paired-valid reporting cells; includes response outside the changed cells."},
        changed_cell_density={
            "area_ha": local_area,
            "baseline_total": changed_totals[0] if local_area else None,
            "alternative_total": changed_totals[1] if local_area else None,
            "delta_total": local_delta, "reduction_total": -local_delta if local_delta is not None else None,
            "baseline": _area_ratio(changed_totals[0], local_area),
            "alternative": _area_ratio(changed_totals[1], local_area),
            "delta": _area_ratio(local_delta, local_area),
            "reduction": _area_ratio(-local_delta if local_delta is not None else None, local_area),
            "numerator": "Annual mass on paired-valid reporting cells whose inputs actually changed; not whole-reporting response."})
    return result


def _pair_metrics(workspace, baseline, alternative, reporting_cells, pixel_area_ha, comparison):
    import numpy as np
    import rasterio
    models = selected_models(baseline["selection"])
    if selected_models(alternative["selection"]) != models:
        raise ValueError("Experiment pairs must select the same native models")
    pollutants = output_models(models)
    for run in (baseline, alternative):
        missing = set(pollutants) - set(run["artifacts"])
        if missing:
            raise ValueError("The selected model run lacks completed outputs: " + ", ".join(sorted(missing)))
    context = _area_source_context(workspace, baseline, alternative)
    domain_geometry = None
    metrics = {}
    for pollutant in pollutants:
        units = rasters.MASS_UNITS[pollutant]
        base_artifact = baseline["artifacts"][pollutant]
        alt_artifact = alternative["artifacts"][pollutant]
        if base_artifact.get("units") != units or alt_artifact.get("units") != units:
            raise ValueError("Experiment totals require the original delivered per-pixel annual masses")
        base_path = verify_file(workspace.root / "runs" / baseline["id"], base_artifact)
        alt_path = verify_file(workspace.root / "runs" / alternative["id"], alt_artifact)
        baseline_total = alternative_total = 0.0
        paired_cells = baseline_cells = alternative_cells = 0
        support = hashlib.sha256()
        footprint = hashlib.sha256()
        changed_codes, changes, global_changes = _area_table_changes(context, pollutant)
        counts = dict.fromkeys(("domain_valid_cells", "landcover_support_changed_cells",
                                "landcover_changed_cells", "coefficient_changed_cells",
                                "changed_cells", "reporting_changed_cells", "paired_changed_cells"), 0)
        changed_totals = [0.0, 0.0]
        with contextlib.ExitStack() as stack:
            a = stack.enter_context(rasterio.open(base_path))
            b = stack.enter_context(rasterio.open(alt_path))
            reporting = stack.enter_context(rasterio.open(context["reporting_path"]))
            rasters.check_same_grid(a, b)
            rasters.check_same_grid(a, reporting)
            transform = a.transform
            actual_area = abs(transform.a * transform.e - transform.b * transform.d) / 10000.0
            if (not a.crs or not a.crs.is_projected
                    or str(a.crs.linear_units).lower() not in ("metre", "meter", "metres", "meters")
                    or not math.isfinite(actual_area) or actual_area <= 0
                    or not math.isclose(actual_area, pixel_area_ha, rel_tol=1e-10, abs_tol=1e-12)
                    or not math.isclose(actual_area, float(context["grid"]["grid"]["pixel_area_ha"]),
                                        rel_tol=1e-10, abs_tol=1e-12)):
                raise ValueError("Per-area results require the exact original projected metre grid and pixel area")
            land = None
            if not context["unavailable"]:
                from rasterio.features import rasterize
                land = [stack.enter_context(rasterio.open(side["landcover"])) for side in context["sides"]]
                for source in land:
                    rasters.check_same_grid(a, source)
                if domain_geometry is None:
                    geometries, _ = rasters.vector_geometry(context["domain_path"], layer="model_domain",
                                                           target_crs=a.crs)
                    domain_geometry = rasters.polygon_union(geometries)
            footprint.update(canonical({"schema": AREA_METRICS_SCHEMA, "grid_id": baseline["selection"]["grid_id"],
                                        "pollutant": pollutant, "changes": changes,
                                        "baseline": context["sides"][0]["source"],
                                        "alternative": context["sides"][1]["source"]}))
            support.update(canonical({"grid_id": baseline["selection"]["grid_id"],
                                      "width": a.width, "height": a.height}))
            for _, window in a.block_windows(1):
                av = a.read(1, window=window, masked=True)
                bv = b.read(1, window=window, masked=True)
                ad = np.ma.getdata(av).astype("float64")
                bd = np.ma.getdata(bv).astype("float64")
                a_good = ~np.ma.getmaskarray(av) & np.isfinite(ad)
                b_good = ~np.ma.getmaskarray(bv) & np.isfinite(bd)
                paired = a_good & b_good
                in_reporting = reporting.read(1, window=window) == 1
                if np.any((a_good | b_good) & ~in_reporting):
                    raise ValueError("Delivered experiment mass contains valid cells outside its retained reporting mask")
                if land is not None:
                    lv = [source.read(1, window=window, masked=True) for source in land]
                    data = [np.ma.getdata(value) for value in lv]
                    good = [~np.ma.getmaskarray(value) & np.isfinite(raw)
                            for value, raw in zip(lv, data)]
                    domain = rasterize([(domain_geometry, 1)], out_shape=ad.shape,
                                       transform=a.window_transform(window), fill=0,
                                       all_touched=False, dtype="uint8") == 1
                    valid = domain & good[0] & good[1]
                    for side, raw, mask in zip(context["sides"], data, good):
                        codes = np.unique(raw[domain & mask])
                        if any(float(code) != int(code) or int(code) not in side["rows"] for code in codes):
                            raise ValueError("A retained native land-cover class lacks its exact coefficient row")
                    lc_changed = valid & (data[0] != data[1])
                    coefficient_changed = valid & (data[0] == data[1]) & np.isin(data[0], list(changed_codes))
                    changed = lc_changed | coefficient_changed
                    changed_reporting = changed & in_reporting
                    changed_paired = changed_reporting & paired
                    counts["domain_valid_cells"] += int(valid.sum())
                    counts["landcover_support_changed_cells"] += int((domain & (good[0] ^ good[1])).sum())
                    counts["landcover_changed_cells"] += int(lc_changed.sum())
                    counts["coefficient_changed_cells"] += int(coefficient_changed.sum())
                    counts["changed_cells"] += int(changed.sum())
                    counts["reporting_changed_cells"] += int(changed_reporting.sum())
                    counts["paired_changed_cells"] += int(changed_paired.sum())
                    changed_totals[0] += float(ad[changed_paired].sum(dtype="float64"))
                    changed_totals[1] += float(bd[changed_paired].sum(dtype="float64"))
                    footprint.update(canonical([int(window.col_off), int(window.row_off),
                                                int(window.width), int(window.height)]))
                    for mask in (valid, changed, changed_reporting, changed_paired):
                        footprint.update(np.packbits(mask, bitorder="little").tobytes())
                baseline_cells += int(a_good.sum())
                alternative_cells += int(b_good.sum())
                paired_cells += int(paired.sum())
                baseline_total += float(ad[paired].sum(dtype="float64"))
                alternative_total += float(bd[paired].sum(dtype="float64"))
                support.update(canonical([int(window.col_off), int(window.row_off),
                                          int(window.width), int(window.height)]))
                support.update(np.packbits(paired, bitorder="little").tobytes())
        delta = alternative_total - baseline_total if paired_cells else None
        metric = {
            "units": units.replace("/pixel", ""),
            "baseline_total": baseline_total if paired_cells else None,
            "alternative_total": alternative_total if paired_cells else None,
            "delta": delta, "reduction": -delta if delta is not None else None,
            "relative_change_pct": 100.0 * delta / baseline_total if paired_cells and baseline_total > 0 else None,
            "paired_cells": paired_cells, "baseline_valid_cells": baseline_cells,
            "alternative_valid_cells": alternative_cells, "reporting_cells": reporting_cells,
            "coverage_fraction": paired_cells / reporting_cells,
            "paired_area_ha": paired_cells * pixel_area_ha,
            "support_sha256": support.hexdigest(),
            "direction": "alternative minus baseline",
        }
        metric["per_area"] = _area_result(metric, pollutant, context, counts, changed_totals,
                                          changes, global_changes, footprint.hexdigest())
        if comparison is not None:
            artifact = comparison["alternatives"][0]["artifacts"][pollutant]
            metric["difference_raster_sum"] = artifact["sum_change"]
        metrics[pollutant] = metric
    return metrics


def _records(directory):
    result = []
    plan = read_json(directory / "plan.json")
    if digest(plan) != directory.name:
        raise ValueError("The original experiment plan identity changed")
    source_runs = {row["run_id"]: row for row in plan.get("source_runs", [])}
    lineage_keys = ("source_run_id", "source_baseline_run_id", "source_selection")
    for path in (directory / "cases").glob("*.json"):
        value = read_json(path)
        identity = {key: value[key] for key in ("run_id", "baseline_run_id", "kind")}
        for field, run_field in (("native_source", "run_id"),
                                 ("native_baseline_source", "baseline_run_id")):
            expected_source = source_runs.get(value[run_field])
            if value.get(field) != expected_source:
                raise ValueError("A retained experiment case differs from its frozen original native source")
        retained_lineage = [key in value for key in lineage_keys]
        if any(retained_lineage):
            if not all(retained_lineage):
                raise ValueError("A retained experiment case has incomplete source lineage")
            source = value["source_selection"]
            current = value["selection"]
            if (not isinstance(source, dict) or not isinstance(current, dict)
                    or digest(source) != value["source_run_id"]
                    or "models" in source
                    or source != {key: item for key, item in current.items() if key != "models"}):
                raise ValueError("A retained experiment case has changed source selection")
            # A recovered partial-model case keeps its original plan case ID.
            # Its current native selection is independently checked below.
            identity = {"run_id": value["source_run_id"],
                        "baseline_run_id": value["source_baseline_run_id"],
                        "kind": value["kind"]}
        if (value.get("schema") != CASE_SCHEMA or value.get("id") != path.stem
                or digest(identity) != path.stem or digest(value["selection"]) != value["run_id"]):
            raise ValueError("A retained experiment case has changed")
        result.append(value)
    return sorted(result, key=lambda row: row["ordinal"])


def _envelope(rows, pollutant):
    values = [row["metrics"][pollutant] for row in rows
              if row["metrics"].get(pollutant, {}).get("delta") is not None]
    if not values:
        return {"profiles": 0, "minimum_delta": None, "maximum_delta": None,
                "minimum_reduction": None, "maximum_reduction": None,
                "minimum_relative_change_pct": None, "maximum_relative_change_pct": None,
                "response": "no paired cells"}
    deltas = [value["delta"] for value in values]
    reductions = [value["reduction"] for value in values]
    percentages = [value["relative_change_pct"] for value in values
                   if value["relative_change_pct"] is not None]
    if all(value == 0 for value in deltas):
        response = "unchanged"
    elif all(value <= 0 for value in deltas):
        response = "lower export across evaluated profiles"
    elif all(value >= 0 for value in deltas):
        response = "higher export across evaluated profiles"
    else:
        response = "direction changes across evaluated profiles"
    return {
        "profiles": len(values), "units": values[0]["units"],
        "minimum_delta": min(deltas), "maximum_delta": max(deltas),
        "minimum_reduction": min(reductions), "maximum_reduction": max(reductions),
        "minimum_relative_change_pct": min(percentages) if percentages else None,
        "maximum_relative_change_pct": max(percentages) if percentages else None,
        "response": response,
    }


def _sensitivity(rows, selection, expected_profiles, pollutants=None):
    result = []
    for scenario_id in selection["scenario_ids"]:
        completed = [row for row in rows if row["kind"] == "landcover"
                     and row["scenario_id"] == scenario_id and row["state"] == "complete"]
        entry = {"scenario_id": scenario_id,
                 "scenario_title": completed[0]["scenario_title"] if completed else None,
                 "completed_profiles": len(completed), "expected_profiles": expected_profiles,
                 "complete": len(completed) == expected_profiles, "pollutants": {}}
        for pollutant in pollutants if pollutants is not None else rasters.MASS_UNITS:
            groups = {}
            for row in completed:
                metric = row["metrics"].get(pollutant)
                if metric is not None and metric.get("delta") is not None:
                    groups.setdefault(metric["support_sha256"], []).append(row)
            common = len(groups) == 1
            value = {"comparable_support": common, "support_groups": []}
            for support, selected in sorted(groups.items()):
                value["support_groups"].append({
                    "support_sha256": support,
                    "profile_ids": [row["profile_id"] for row in selected],
                    "paired_cells": selected[0]["metrics"][pollutant]["paired_cells"],
                    **_envelope(selected, pollutant),
                })
            if common:
                value.update(_envelope(completed, pollutant))
            else:
                value.update({"profiles": len(completed), "minimum_delta": None,
                              "maximum_delta": None, "minimum_reduction": None,
                              "maximum_reduction": None,
                              "minimum_relative_change_pct": None,
                              "maximum_relative_change_pct": None,
                              "response": "compare the separate valid-cell support groups" if groups else "awaiting completed pairs"})
            entry["pollutants"][pollutant] = value
        result.append(entry)
    return result


def _csv_text(value):
    text = str(value)
    return "'" + text if text.startswith(("=", "+", "-", "@", "\t", "\r", "\n")) else text


def _csv_bytes(rows):
    output = io.StringIO(newline="")
    columns = ("case_id", "kind", "state", "profile_id", "profile_title", "scenario_id",
               "scenario_title", "models", "run_id", "baseline_run_id", "comparison_id",
               "parameters", "pollutant", "units", "baseline_total", "alternative_total",
               "delta", "reduction", "relative_change_pct", "paired_cells",
               "baseline_valid_cells", "alternative_valid_cells", "reporting_cells",
               "coverage_fraction", "paired_area_ha", "support_sha256", "error",
               "per_area_units", "per_area_status", "baseline_per_paired_ha", "alternative_per_paired_ha",
               "delta_per_paired_ha", "reduction_per_paired_ha", "changed_input_area_ha",
               "changed_input_reporting_area_ha", "changed_input_paired_area_ha",
               "changed_input_reporting_coverage", "whole_reporting_delta_per_changed_ha",
               "whole_reporting_reduction_per_changed_ha", "response_per_changed_ha_reason",
               "changed_cell_delta_density", "changed_cell_reduction_density",
               "changed_landcover_cells", "changed_coefficient_cells", "changed_input_sha256",
               "global_parameter_changes", "changed_input_sources")
    writer = csv.DictWriter(output, fieldnames=columns)
    writer.writeheader()
    for row in rows:
        common = {key: row.get(key) for key in ("kind", "state", "profile_id", "scenario_id",
                  "run_id", "baseline_run_id", "comparison_id")}
        common.update(case_id=row["id"], models=",".join(selected_models(row["selection"])),
                      profile_title=_csv_text(row["profile_title"]),
                      scenario_title=_csv_text(row["scenario_title"]),
                      parameters=_csv_text(json.dumps(row["changes"], ensure_ascii=False, sort_keys=True)),
                      error=_csv_text(row.get("error", {}).get("message", "")))
        if row["state"] != "complete":
            writer.writerow(common)
            continue
        for pollutant, metric in row["metrics"].items():
            area = metric.get("per_area", {})
            paired = area.get("paired_reporting", {})
            footprint = area.get("input_footprint", {})
            response = area.get("whole_reporting_response_per_changed_ha", {})
            density = area.get("changed_cell_density", {})
            writer.writerow({**common, "pollutant": pollutant,
                             **{key: metric.get(key) for key in columns if key in metric},
                             "per_area_units": area.get("units"), "per_area_status": area.get("status"),
                             "baseline_per_paired_ha": paired.get("baseline_total"),
                             "alternative_per_paired_ha": paired.get("alternative_total"),
                             "delta_per_paired_ha": paired.get("delta"),
                             "reduction_per_paired_ha": paired.get("reduction"),
                             "changed_input_area_ha": footprint.get("area_ha"),
                             "changed_input_reporting_area_ha": footprint.get("reporting_area_ha"),
                             "changed_input_paired_area_ha": footprint.get("paired_area_ha"),
                             "changed_input_reporting_coverage": footprint.get("paired_fraction_of_reporting_changed"),
                             "whole_reporting_delta_per_changed_ha": response.get("delta"),
                             "whole_reporting_reduction_per_changed_ha": response.get("reduction"),
                             "response_per_changed_ha_reason": _csv_text(response.get("reason") or area.get("reason") or ""),
                             "changed_cell_delta_density": density.get("delta"),
                             "changed_cell_reduction_density": density.get("reduction"),
                             "changed_landcover_cells": footprint.get("landcover_changed_cells"),
                             "changed_coefficient_cells": footprint.get("coefficient_changed_cells"),
                             "changed_input_sha256": footprint.get("sha256"),
                             "global_parameter_changes": _csv_text(json.dumps(footprint.get("global_parameter_changes", []), ensure_ascii=False, sort_keys=True)),
                             "changed_input_sources": _csv_text(json.dumps(footprint.get("sources", {}), ensure_ascii=False, sort_keys=True))})
    return output.getvalue().encode("utf-8-sig")


def _summarize_locked(workspace, experiment_id, plan, state):
    directory = _directory(workspace, experiment_id)
    rows = _records(directory)
    # Enrich historical completed cases once from their retained inputs/outputs.
    # Their original case identity, completion metadata, totals and artifacts stay intact.
    reporting_context = None
    for row in rows:
        if row["state"] != "complete" or (row.get("metrics") and all(
                value.get("per_area", {}).get("schema") == AREA_METRICS_SCHEMA
                for value in row["metrics"].values())):
            continue
        reference = workspace.inspect_run(row["baseline_run_id"])
        alternative = workspace.inspect_run(row["run_id"])
        if reporting_context is None:
            reporting_context = _reporting_cells(workspace, plan["baseline"]["grid_id"])
        count, area = reporting_context
        enriched = _pair_metrics(workspace, reference, alternative, count, area, None)
        for pollutant, value in enriched.items():
            retained = row["metrics"][pollutant]
            for name in ("baseline_total", "alternative_total", "paired_cells", "support_sha256"):
                if retained.get(name) != value.get(name):
                    raise ValueError("Retained experiment mass/support differs while adding per-area context: " + name)
            retained["per_area"] = value["per_area"]
        _persist_case(directory, row)
    models = selected_models(plan["baseline"])
    pollutants = output_models(models)
    generated = now()
    summary = {
        "schema": SUMMARY_SCHEMA, "id": experiment_id, "workspace_id": workspace.project["id"],
        "title": state["title"], "reason": plan["selection"]["reason"],
        "state": state["state"], "selection": plan["selection"], "baseline": plan["baseline"],
        "counts": plan["counts"], "progress": copy.deepcopy(state["progress"]),
        "generated_at": generated, "rows": rows, "area_metrics_schema": AREA_METRICS_SCHEMA,
        "models": list(models), "pollutants": list(pollutants),
        "grid_id": plan["baseline"]["grid_id"],
        "pairs": [{"profile_id": row["profile_id"], "baseline_run_id": row["baseline_run_id"],
                   "alternative_run_id": row["run_id"], "scenario_id": row["scenario_id"]}
                  for row in rows if row["kind"] == "landcover" and row["state"] == "complete"],
        "sensitivity": _sensitivity(rows, plan["selection"], plan["counts"]["profiles"], pollutants),
        "interpretation": {
            "landcover": "Alternative land cover minus the baseline under the same parameter profile.",
            "parameter": "Baseline land cover under a selected profile minus the original reference profile.",
            "totals": "Delivered per-pixel annual masses summed over the same valid cells for each pair.",
            "positive_delta": "Higher annual export", "negative_delta": "Lower annual export",
            "ranges": "Sensitivity ranges over the explicitly evaluated profiles.",
            "zero_baseline": "Relative change is undefined when the paired baseline total is zero.",
            "reporting_density": "Paired annual reporting mass divided by its paired-valid reporting area.",
            "changed_area": "Actual union of pollutant-relevant coefficient and land-cover changes on valid model-domain pixel centres; distinct from reporting area and nominal intervention polygons.",
            "response_per_changed_hectare": "Whole paired-reporting response divided by actual model-domain changed area; distinct from export density on changed cells. Not attributed when global model parameters or land-cover validity also differ.",
        },
        "files": {},
    }
    atomic_bytes(directory / "results.csv", _csv_bytes(rows))
    summary["files"]["csv"] = describe_file(directory, directory / "results.csv")
    atomic_json(directory / "summary.json", summary)
    files = {**summary["files"], "json": describe_file(directory, directory / "summary.json")}
    state.update(files=files, summary_at=generated, updated_at=generated)
    atomic_json(directory / "state.json", state)
    return {**summary, "files": files}


def summarize(workspace, experiment_id):
    plan = _plan(workspace, experiment_id)
    directory = _directory(workspace, experiment_id)
    with held(directory / ".experiment.lock", blocking=False):
        state = _recover_case_bindings(workspace, plan, directory, _state(workspace, experiment_id))
        # Owning this lock establishes that no experiment executor is active.
        # Recover interrupted case markers before producing an operator report.
        for case in _records(directory):
            if case["state"] == "running":
                case.update(state="failed", updated_at=now(),
                            error={"type": "InterruptedExperiment",
                                   "message": "Execution stopped before this case was finalized; resume the experiment"})
                _persist_case(directory, case)
        state = _progress(directory, state)
        if state["progress"]["complete"] == plan["counts"]["cases"]:
            state.update(state="complete", completed_at=state.get("completed_at") or now())
            state.pop("error", None)
        elif state["progress"]["failed"] or state["state"] == "running":
            state["state"] = "partial" if state["progress"]["complete"] else "failed"
            state.pop("completed_at", None)
        else:
            state["state"] = "partial" if state["progress"]["complete"] else "prepared"
            state.pop("completed_at", None)
        return _summarize_locked(workspace, experiment_id, plan, state)


def read_summary(workspace, experiment_id):
    plan = _plan(workspace, experiment_id)
    directory = _directory(workspace, experiment_id)
    path = directory / "summary.json"
    if not path.exists():
        return None
    summary = read_json(path)
    if (summary.get("schema") != SUMMARY_SCHEMA or summary.get("id") != experiment_id
            or summary.get("workspace_id") != workspace.project["id"]):
        raise ValueError("The retained summary belongs to another experiment")
    models = selected_models(plan["baseline"])
    if selected_models(summary) != models:
        return None
    if (summary.get("state") == "complete"
            and summary.get("progress", {}).get("complete") != plan["counts"]["cases"]):
        return None
    if plan.get("_legacy_case_ids"):
        state = _state(workspace, experiment_id)
        if (state.get("native_binding_models") != models
                or (state.get("bindings_recovered_at") and not state.get("summary_at"))):
            return None
    return {**summary, "files": {**summary.get("files", {}),
                                 "json": describe_file(directory, path)}}


def _remember_reuse_source(candidates, case):
    """Keep the reference and recent same-scenario donors while streaming cases."""
    values = candidates.setdefault(case["scenario_id"], [])
    if case["run_id"] not in values:
        values.append(case["run_id"])
        # This is an opportunistic cache, not a limit on the experiment matrix.
        # Preserve the first profile and the latest fifteen; the native indexed
        # cache continues to find exact inputs throughout the entire workspace.
        if len(values) > 16:
            del values[1]


def execute(workspace, experiment_id, *, completed_only=False):
    if type(completed_only) is not bool:
        raise ValueError("Choose whether to synchronize completed native runs only")
    plan = _plan(workspace, experiment_id)
    directory = _directory(workspace, experiment_id)
    # Use the existing native batch lock as well as the experiment's mutation
    # lock. The operator's original queue remains the entry point for jobs.
    with held(directory / ".experiment.lock", blocking=False), held(
            workspace.root / ".native-model-batch.lock", blocking=False):
        state = _recover_case_bindings(workspace, plan, directory, _state(workspace, experiment_id))
        state = _progress(directory, state)
        if state["progress"]["complete"] == plan["counts"]["cases"]:
            state["state"] = "complete"
            previous = read_summary(workspace, experiment_id)
            if (previous is not None and previous["state"] == "complete"
                    and previous.get("area_metrics_schema") == AREA_METRICS_SCHEMA
                    and previous["progress"]["complete"] == plan["counts"]["cases"]):
                atomic_json(directory / "state.json", state)
                return {**state, "reused": True}
            _summarize_locked(workspace, experiment_id, plan, state)
            return state
        state.update(state="running", started_at=state.get("started_at") or now())
        state.pop("error", None)
        atomic_json(directory / "state.json", state)
        active = None
        reuse_sources = {}
        try:
            if "reporting_cells" not in state:
                count, area = _reporting_cells(workspace, plan["baseline"]["grid_id"])
                state.update(reporting_cells=count, pixel_area_ha=area)
                atomic_json(directory / "state.json", state)
            for expected, option in _case_definitions(workspace, plan):
                case = _retained_case(directory, expected)
                if case["state"] == "complete":
                    _remember_reuse_source(reuse_sources, case)
                    continue
                active = case
                if case["state"] == "failed":
                    state["progress"]["failed"] -= 1
                    state["progress"]["pending"] += 1
                case.update(state="running", started_at=now(),
                            attempts=case.get("attempts", 0) + 1)
                case.pop("error", None)
                _persist_case(directory, case)
                state["progress"]["active_case_id"] = case["id"]
                state["updated_at"] = now()
                atomic_json(directory / "state.json", state)
                run = None
                try:
                    run = _prepare_case_run(workspace, case, option)
                    if run["state"] != "complete":
                        if completed_only:
                            raise RuntimeError("Complete the selected native run before synchronizing experiment results")
                        # Profile tables can differ only in the other model's
                        # columns. Retain explicit same-scenario candidates so
                        # the native matcher can compare the relevant inputs.
                        donors = list(dict.fromkeys(
                            list(run.get("reuse_source_run_ids", [])) +
                            list(reversed(reuse_sources.get(case["scenario_id"], [])))))
                        donors = [key for key in donors if key != run["id"]]
                        run = (workspace.run(run["id"], reuse_source_run_ids=donors)
                               if donors else workspace.run(run["id"]))
                    if run["state"] != "complete":
                        raise RuntimeError("The selected native model run has not completed")
                    reference = workspace.inspect_run(case["baseline_run_id"])
                    if reference["state"] != "complete":
                        raise RuntimeError("The paired baseline is unfinished; the alternative native outputs are retained")
                    producing_versions = comparison_versions(
                        [reference, run], selected_models(case["selection"]))
                    comparison = None
                    if reference["id"] != run["id"]:
                        comparison = workspace.compare_runs([reference["id"], run["id"]])
                    metrics = _pair_metrics(workspace, reference, run, state["reporting_cells"],
                                            state["pixel_area_ha"], comparison)
                    case.update(state="complete", completed_at=now(), metrics=metrics,
                                comparison_id=comparison["id"] if comparison else None,
                                native_completed_at=run["completed_at"],
                                native_runtime=run.get("runtime"),
                                native_versions=producing_versions,
                                native_stage_reuse={model: stage["reused_from"]
                                    for model, stage in run.get("stages", {}).items()
                                    if stage.get("reused_from")},
                                output_artifacts=run["artifacts"])
                    state["progress"]["complete"] += 1
                except Exception as exc:
                    failure = copy.deepcopy(getattr(exc, "native_failure", None)) or {
                        "type": type(exc).__name__, "message": str(exc)}
                    case.update(state="failed", updated_at=now(), error=failure)
                    state["progress"]["failed"] += 1
                    if storage_exhausted(exc):
                        raise
                if run is not None:
                    # A failed later model may still leave a complete reusable
                    # earlier stage. The native matcher verifies each stage.
                    _remember_reuse_source(reuse_sources, case)
                state["progress"]["pending"] -= 1
                state["progress"]["active_case_id"] = None
                state["updated_at"] = now()
                _persist_case(directory, case)
                atomic_json(directory / "state.json", state)
                active = None
            state = _progress(directory, state)
            if state["progress"]["failed"]:
                state["state"] = "partial" if state["progress"]["complete"] else "failed"
                state["error"] = {"type": "IncompleteExperiment",
                                  "message": str(state["progress"]["failed"]) + " experiment cases need resuming"}
            else:
                state.update(state="complete", completed_at=now())
                state.pop("error", None)
            _summarize_locked(workspace, experiment_id, plan, state)
        except BaseException as exc:
            capacity_failure = storage_exhausted(exc)
            failure = copy.deepcopy(getattr(exc, "native_failure", None)) or {
                "type": type(exc).__name__, "message": str(exc)}
            try:
                if active is not None and active.get("state") != "complete":
                    active.update(state="failed", updated_at=now(), error=failure)
                    _persist_case(directory, active)
                state = _progress(directory, state)
                state["state"] = "partial" if state["progress"]["complete"] else "failed"
                state["error"] = failure
                atomic_json(directory / "state.json", state)
            except OSError:
                if not capacity_failure:
                    raise
            # Existing completed exports remain available. A full filesystem
            # needs capacity recovery before another aggregation/export write.
            if not capacity_failure:
                try:
                    _summarize_locked(workspace, experiment_id, plan, state)
                except Exception:
                    pass
            raise
        if state["state"] != "complete":
            raise RuntimeError("Experiment " + experiment_id + ": " + state["error"]["message"])
        return state

files.model/geographic_scenario_contrasts.py:
"""Describe the physical inputs at actual geographic scenario change pixels.

This is a bounded-window companion to the original allocation pass. The shared
prepared scalar inputs do not change between scenarios. These statistics describe
where each scenario changed land cover; they are not native NDR/SDR outputs.
"""
from __future__ import annotations

from copy import deepcopy
import csv
import math
from pathlib import Path

from .common import atomic_json, identifier, verify_file

SCHEMA = "upstate.geographic-scenario-physical-contrasts/v1"
EDITION = "prepared-input-contrasts/1"
ROLES = ("DEM", "PRECIPITATION", "R_FACTOR", "K_FACTOR")
VARIABLES = ROLES + ("R_TIMES_K",)
ARMS = ("restoration", "control")
CLASSES = ("all", "81", "82", "other")
UNITS = {"DEM": "m", "R_FACTOR": "MJ*mm/(ha*h*year)",
         "K_FACTOR": "t*ha*h/(ha*MJ*mm)", "R_TIMES_K": "t/(ha*year)"}
LABELS = {"DEM": "Elevation", "PRECIPITATION": "NDR runoff proxy",
          "R_FACTOR": "Rainfall erosivity factor R", "K_FACTOR": "Soil erodibility factor K",
          "R_TIMES_K": "Input-factor product R × K"}
MEMBERS = ("physical-contrasts.json", "physical-contrasts.csv", "physical-distributions.csv")
NOTES = [
    "The same original prepared scalar grids are used by all three native scenarios. Differences describe the geographic selection of changed pixels, not scenario-induced changes to rain, soil or elevation.",
    "Each arm contains its actual final baseline-to-alternative changed cells on the region's three-scenario common categorical support. Classes 81 and 82 refer to the original baseline; other contains every remaining baseline code. The all row includes all three class groups.",
    "Each scalar has its own finite, unmasked support. Valid and missing counts refer to the explicit arm/class denominator; restoration/control overlap remains visible and is not assumed absent.",
    "R minus C is a descriptive difference between independently supported pixel means. It is not a causal treatment effect, matched-pair estimate, significance test or pollutant-load difference.",
    "Population standard deviation uses centered per-window moments and stable Chan merging. Equal-area prepared cells receive equal weight; these are selected raster-pixel statistics, not vector-polygon samples.",
    "Shared histogram edges use the original whole prepared-grid minimum and maximum, so regions and arms share a declared scale. R × K bounds enclose the product using nonnegative original factor bounds; they are not observed product extrema. No quantiles are inferred.",
    "R × K has units t/(ha*year) only for the declared original factor units. It is an input-factor product without slope-length, cover, practice or routing factors; it is not SDR erosion or sediment export. Elevation is not a slope or LS proxy.",
    "Precipitation retains its original declared units and is described as a runoff proxy unless the aligned source explicitly declares mm/year. No area multiplication, second conversion or resampling is applied.",
]


def _bounds(item, label):
    count = item.get("valid_cells")
    if isinstance(count, bool) or not isinstance(count, int) or count < 0:
        raise ValueError(label + " needs its original prepared valid-cell count")
    low, high = item.get("minimum"), item.get("maximum")
    if count == 0:
        if low is not None or high is not None:
            raise ValueError(label + " has inconsistent empty prepared bounds")
        return None
    if (isinstance(low, bool) or isinstance(high, bool)
            or not isinstance(low, (int, float)) or not isinstance(high, (int, float))
            or not math.isfinite(low) or not math.isfinite(high) or low > high):
        raise ValueError(label + " needs finite original prepared-grid bounds")
    return [float(low), float(high)]


def _histogram(bounds):
    if bounds is None:
        return {"basis": "original prepared grid has no valid cells", "edges": [],
                "constant_value": None, "bin_count": 0}
    low, high = bounds
    if low == high:
        return {"basis": "original whole prepared-grid bounds", "edges": [low, high],
                "constant_value": low, "bin_count": 1}
    import numpy as np
    edges = np.linspace(low, high, 33, dtype=np.float64)
    if not np.all(np.diff(edges) > 0):
        raise ValueError("Prepared input bounds cannot define distinct shared histogram edges")
    return {"basis": "original whole prepared-grid bounds", "edges": edges.tolist(),
            "constant_value": None, "bin_count": 32}


def bind(workspace, grid_record):
    """Bind original aligned files and exact retained source metadata without views."""
    key = identifier(grid_record["id"])
    collection_id = identifier(grid_record["spec"]["source_collection_id"])
    collection = workspace._get("sources", collection_id)
    entries = {entry["id"]: entry for entry in collection["entries"]}
    directory = workspace.root / "grids" / key
    variables = {}
    for role in ROLES:
        descriptor = grid_record["files"].get(role)
        original = grid_record["inputs"].get(role)
        if descriptor is None and original is None:
            variables[role] = {"available": False, "label": LABELS[role], "units": None,
                               "reason": "Not prepared for the selected native model scope",
                               "histogram": _histogram(None)}
            continue
        if descriptor is None or original is None:
            raise ValueError("Prepared physical input lost its original file or provenance: " + role)
        source_id = grid_record["spec"]["input_sources"].get(role)
        entry = entries.get(source_id)
        if (entry is None or entry["kind"] != "raster" or original["source_id"] != source_id
                or original["source_sha256"] != entry["body"]["sha256"]
                or original["source_uri"] != entry["uri"] or original["vintage"] != entry["vintage"]):
            raise ValueError("Prepared physical input no longer matches its original source: " + role)
        units = descriptor.get("units")
        conversion = entry.get("conversion")
        source_units = conversion.get("target_units") if conversion else entry.get("units")
        if units != source_units or role in UNITS and units != UNITS[role]:
            raise ValueError("Retain the original prepared physical input units: " + role)
        bounds = _bounds(original, role)
        if role in ("R_FACTOR", "K_FACTOR") and bounds is not None and bounds[0] < 0:
            raise ValueError("Original R and K factors must be nonnegative")
        verify_file(directory, descriptor)
        variables[role] = {
            "available": True, "label": ("Annual precipitation" if role == "PRECIPITATION"
                                        and units == "mm/year" else LABELS[role]),
            "units": units, "aligned_file": deepcopy(descriptor),
            "prepared_input": deepcopy(original),
            "source": {"source_collection_id": collection_id, "source_id": source_id,
                       "entry": deepcopy(entry)},
            "histogram": _histogram(bounds),
        }
    r, k = variables["R_FACTOR"], variables["K_FACTOR"]
    if r["available"] and k["available"]:
        rb, kb = _bounds(r["prepared_input"], "R"), _bounds(k["prepared_input"], "K")
        bounds = None if rb is None or kb is None else [rb[0] * kb[0], rb[1] * kb[1]]
        if bounds is not None and not all(math.isfinite(value) for value in bounds):
            raise ValueError("Original R × K enclosing bounds are not finite")
        histogram = _histogram(bounds)
        histogram["basis"] = "nonnegative whole-grid factor bounds; enclosing, not observed product extrema"
        variables["R_TIMES_K"] = {
            "available": True, "label": LABELS["R_TIMES_K"], "units": UNITS["R_TIMES_K"],
            "derived_from": ["R_FACTOR", "K_FACTOR"], "histogram": histogram,
        }
    else:
        variables["R_TIMES_K"] = {
            "available": False, "label": LABELS["R_TIMES_K"], "units": UNITS["R_TIMES_K"],
            "reason": "Both original prepared R and K factors are required",
            "histogram": _histogram(None),
        }
    return {"schema": SCHEMA, "edition": EDITION, "grid_id": key,
            "grid": deepcopy(grid_record["grid"]), "source_collection_id": collection_id,
            "variables": variables, "notes": list(NOTES)}


def open_sources(workspace, binding, stack):
    import rasterio
    from rasterio.crs import CRS
    from rasterio.transform import Affine
    grid = binding["grid"]
    result = {}
    for role in ROLES:
        variable = binding["variables"][role]
        if not variable["available"]:
            continue
        path = verify_file(workspace.root / "grids" / binding["grid_id"], variable["aligned_file"])
        source = stack.enter_context(rasterio.open(path))
        if (source.count != 1 or source.width != grid["width"] or source.height != grid["height"]
                or source.transform != Affine(*grid["transform"])
                or source.crs != CRS.from_user_input(grid["crs"])):
            raise ValueError("Physical contrasts require the exact original single-band prepared grid")
        result[role] = source
    return result


def read_window(sources, window, binding):
    """Read each prepared scalar once per original allocation window."""
    import numpy as np
    result = {}
    for role, source in sources.items():
        data = source.read(1, window=window, masked=True)
        values = np.asarray(np.ma.getdata(data), dtype=np.float64)
        valid = ~np.ma.getmaskarray(data) & np.isfinite(values)
        if role in ("R_FACTOR", "K_FACTOR") and np.any(valid & (values < 0)):
            raise ValueError("Original prepared R/K contains a negative physical value")
        result[role] = (values, valid)
    if binding["variables"]["R_TIMES_K"]["available"]:
        r, rv = result["R_FACTOR"]
        k, kv = result["K_FACTOR"]
        valid = rv & kv
        values = np.zeros(r.shape, dtype=np.float64)
        values[valid] = r[valid] * k[valid]
        if np.any(valid & ~np.isfinite(values)):
            raise ValueError("Original prepared R × K product is not finite")
        result["R_TIMES_K"] = (values, valid)
    return result


def _moment(variable):
    return {"count": 0, "mean": 0.0, "m2": 0.0, "minimum": None, "maximum": None,
            "histogram": [0] * variable["histogram"]["bin_count"]}


def empty(binding):
    return {"classes": {
        group: {"common_categorical_cells": 0, "overlap_changed_cells": 0,
                "changed_cells": dict.fromkeys(ARMS, 0),
                "samples": {arm: {role: _moment(binding["variables"][role])
                                  for role in VARIABLES} for arm in ARMS}}
        for group in CLASSES}}


def _add(moment, data, variable):
    import numpy as np
    count = int(data.size)
    if not count:
        return
    spec = variable["histogram"]
    if not spec["edges"]:
        raise ValueError("A supposedly empty original prepared input contains valid selected cells")
    low, high = spec["edges"][0], spec["edges"][-1]
    minimum, maximum = float(np.min(data)), float(np.max(data))
    if minimum < low or maximum > high:
        raise ValueError("Selected physical values exceed their original whole-grid histogram bounds")
    mean = float(np.mean(data, dtype=np.float64))
    centered = data - mean
    m2 = float(np.dot(centered, centered))
    if spec["constant_value"] is not None:
        counts = [count]
    else:
        counts = [int(value) for value in np.histogram(data, bins=spec["edges"])[0]]
    if sum(counts) != count or not math.isfinite(mean) or not math.isfinite(m2):
        raise ValueError("Physical statistics lost finite values or histogram support")
    prior, total = moment["count"], moment["count"] + count
    delta = mean - moment["mean"]
    moment["m2"] += m2 + delta * delta * prior * count / total
    moment["mean"] += delta * count / total
    moment["count"] = total
    moment["minimum"] = minimum if moment["minimum"] is None else min(minimum, moment["minimum"])
    moment["maximum"] = maximum if moment["maximum"] is None else max(maximum, moment["maximum"])
    moment["histogram"] = [a + b for a, b in zip(moment["histogram"], counts)]


def accumulate(state, arrays, valid, inside, scalars, binding):
    import numpy as np
    common = inside & valid["baseline"] & valid["restoration"] & valid["control"]
    changed = {arm: common & (arrays[arm] != arrays["baseline"]) for arm in ARMS}
    classes = {"all": common, "81": common & (arrays["baseline"] == 81),
               "82": common & (arrays["baseline"] == 82),
               "other": common & (arrays["baseline"] != 81) & (arrays["baseline"] != 82)}
    for group, selected in classes.items():
        record = state["classes"][group]
        record["common_categorical_cells"] += int(np.count_nonzero(selected))
        record["overlap_changed_cells"] += int(np.count_nonzero(
            selected & changed["restoration"] & changed["control"]))
        for arm in ARMS:
            mask = selected & changed[arm]
            count = int(np.count_nonzero(mask))
            record["changed_cells"][arm] += count
            if not count:
                continue
            for role, (values, finite) in scalars.items():
                _add(record["samples"][arm][role], values[mask & finite], binding["variables"][role])


def finish(state, binding):
    area = binding["grid"]["pixel_area_ha"]
    result = {"schema": SCHEMA, "classes": []}
    for group in CLASSES:
        value = state["classes"][group]
        record = {key: deepcopy(value[key]) for key in (
            "common_categorical_cells", "overlap_changed_cells", "changed_cells")}
        record.update(baseline_class=group, overlap_changed_hectares=value["overlap_changed_cells"] * area,
                      samples={}, mean_differences={})
        for arm in ARMS:
            denominator = value["changed_cells"][arm]
            record["samples"][arm] = {}
            for role in VARIABLES:
                variable, moment = binding["variables"][role], value["samples"][arm][role]
                count = moment["count"]
                if count > denominator or sum(moment["histogram"]) != count:
                    raise ValueError("Physical contrast counts no longer match the selected denominator")
                mean = moment["mean"] if count else None
                deviation = math.sqrt(max(0.0, moment["m2"] / count)) if count else None
                if count and (not math.isfinite(mean) or not math.isfinite(deviation)):
                    raise ValueError("Physical contrast moments are not finite")
                record["samples"][arm][role] = {
                    "available": variable["available"], "units": variable["units"],
                    "selected_cells": denominator, "selected_hectares": denominator * area,
                    "valid_cells": count, "missing_cells": denominator - count,
                    "valid_hectares": count * area, "coverage_fraction": count / denominator if denominator else None,
                    "mean": mean, "population_standard_deviation": deviation,
                    "minimum": moment["minimum"], "maximum": moment["maximum"],
                    "histogram_counts": moment["histogram"],
                }
        for role in VARIABLES:
            r, c = (record["samples"][arm][role] for arm in ARMS)
            record["mean_differences"][role] = {
                "restoration_minus_control": (r["mean"] - c["mean"]
                                               if r["valid_cells"] and c["valid_cells"] else None),
                "units": binding["variables"][role]["units"],
                "restoration_valid_cells": r["valid_cells"], "control_valid_cells": c["valid_cells"],
                "basis": "descriptive difference of independently supported pixel means",
            }
        result["classes"].append(record)
    return result


def _csv(path, fields, rows):
    with Path(path).open("w", encoding="utf-8", newline="") as stream:
        writer = csv.DictWriter(stream, fieldnames=fields)
        writer.writeheader()
        writer.writerows(rows)


def write(directory, report):
    """Retain complete per-region moments and distributions before source import."""
    binding = report["identity"]["physical_input_binding"]
    records = [{key: deepcopy(region[key]) for key in (
        "id", "title", "kind", "relationship", "quantity_scope", "physical_contrasts")}
        for region in report["regions"]]
    atomic_json(directory / MEMBERS[0], {
        "schema": SCHEMA, "allocation_id": report["id"], "project_id": report["project_id"],
        "binding": binding, "run_ids": report["run_ids"], "regions": records, "notes": NOTES})
    def rows(distribution=False):
        for region in records:
            identity = {"region_id": region["id"], "region_title": region["title"],
                        "region_kind": region["kind"], "relationship": region["relationship"],
                        "quantity_scope": region["quantity_scope"]}
            for group in region["physical_contrasts"]["classes"]:
                context = {**identity, "baseline_class": group["baseline_class"],
                           "common_categorical_cells": group["common_categorical_cells"],
                           "overlap_changed_cells": group["overlap_changed_cells"]}
                for arm in ARMS:
                    for role in VARIABLES:
                        sample = group["samples"][arm][role]
                        if not distribution:
                            yield {**context, "scenario": arm, "variable": role,
                                   **{key: value for key, value in sample.items() if key != "histogram_counts"},
                                   "restoration_minus_control_mean": group["mean_differences"][role]["restoration_minus_control"]}
                            continue
                        histogram = binding["variables"][role]["histogram"]
                        for index, count in enumerate(sample["histogram_counts"]):
                            yield {**context, "scenario": arm, "variable": role,
                                "units": sample["units"], "bin_index": index,
                                "lower": histogram["edges"][index], "upper": histogram["edges"][index + 1],
                                "upper_inclusive": index == len(sample["histogram_counts"]) - 1,
                                "valid_cells": sample["valid_cells"], "cells": count,
                                "fraction_of_valid": count / sample["valid_cells"] if sample["valid_cells"] else None,
                                "bound_basis": histogram["basis"]}
    context_fields = ["region_id", "region_title", "region_kind", "relationship", "quantity_scope",
                      "baseline_class", "common_categorical_cells", "overlap_changed_cells", "scenario", "variable"]
    _csv(directory / MEMBERS[1], context_fields + [
        "available", "units", "selected_cells", "selected_hectares", "valid_cells", "missing_cells",
        "valid_hectares", "coverage_fraction", "mean", "population_standard_deviation",
        "minimum", "maximum", "restoration_minus_control_mean"], rows())
    _csv(directory / MEMBERS[2], context_fields + [
        "units", "bin_index", "lower", "upper", "upper_inclusive", "valid_cells", "cells",
        "fraction_of_valid", "bound_basis"], rows(distribution=True))


def _number(value):
    return "Unavailable" if value is None else format(value, ".5g")


def sections(report):
    """Compact original report blocks; complete native rows remain downloadable."""
    binding = report["identity"]["physical_input_binding"]
    blocks = list(NOTES)
    inputs = []
    for role in VARIABLES:
        variable = binding["variables"][role]
        inputs.append([role, variable["label"], variable["units"] or "Not declared",
                       "Available" if variable["available"] else variable["reason"]])
    blocks.append({"kind": "table", "columns": ["Input", "Meaning", "Declared units", "Availability"],
                   "rows": inputs, "widths": None, "caption": "Exact aligned native inputs; source identities, conversions and common histogram edges are retained in physical-contrasts.json."})
    blocks.append("Complete physical-contrasts.csv contains every region, original-class group, arm and variable with selected/valid/missing counts, mean, population standard deviation and extrema. physical-distributions.csv contains every shared histogram bin. Classes all/81/82/other and changed-pixel overlap remain explicit.")
    blocks.append({"kind": "links", "items": [
        {"path": MEMBERS[0], "title": "Complete physical-input identities and every regional contrast (JSON)"},
        {"path": MEMBERS[1], "title": "All region, baseline-class and scenario statistics (CSV)"},
        {"path": MEMBERS[2], "title": "All shared physical-input histogram bins (CSV)"},
    ]})
    output = [["Physical setting of the actual changed pixels", blocks]]
    for region in report["regions"]:
        if region["kind"] not in ("whole_selection", "utility_upstream_union"):
            continue
        group = next(value for value in region["physical_contrasts"]["classes"] if value["baseline_class"] == "all")
        rows = []
        for role in VARIABLES:
            r, c = (group["samples"][arm][role] for arm in ARMS)
            rows.append([binding["variables"][role]["label"], r["units"] or "Not declared",
                         str(r["valid_cells"]) + "/" + str(r["selected_cells"]),
                         _number(r["mean"]), str(c["valid_cells"]) + "/" + str(c["selected_cells"]),
                         _number(c["mean"]), _number(group["mean_differences"][role]["restoration_minus_control"])])
        output.append([region["title"] + " — " + region["quantity_scope"] + ": changed-pixel physical inputs", [
            region["relationship"] + ". Restoration/control changed-pixel overlap: " +
            str(group["overlap_changed_cells"]) + " cells. All baseline classes shown; original 81/82/other details remain in the complete data.",
            {"kind": "table", "columns": ["Input", "Units", "R valid/selected", "R mean",
                                         "C valid/selected", "C mean", "R − C mean"],
             "rows": rows, "widths": None,
             "caption": "Descriptive means on each arm's finite input support. They do not estimate scenario-induced physical change or a native pollutant effect."},
        ]])
    return output

files.model/implementation_schema.py:
"""Durable implementation planning and field monitoring, using Python's standard library.

Portable documents use upstate.implementation-plan/v1. Revisions and attachments
live under <workspace.root>/implementation/plans/<id>. The native Workspace is
only consumed through its root attribute. No optimizer, nutrient calculator, or
remote service is invoked by this module.
"""
from __future__ import annotations

import bisect
import copy
import datetime as dt
import hashlib
import json
import math
from pathlib import Path
import re
from typing import Any, Iterable

SCHEMA = "upstate.implementation-plan/v1"
REVISION_SCHEMA = "upstate.implementation-revision/v1"
SAFE_INTEGER = 9007199254740991
MAX_JSON_BYTES = 16 * 1024 * 1024
ID_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9_-]{0,95}$")
DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")
REVISION_RE = re.compile(r"^(\d{16})\.json$")
COLLECTIONS = (
    "source_links", "candidates", "tasks", "budget_lines", "sites",
    "monitoring_plans", "visits", "activities", "observations",
)


class ImplementationError(ValueError):
    """An actionable document or operation error."""


class ValidationError(ImplementationError):
    def __init__(self, issues: Iterable[str]):
        self.issues = list(issues)
        super().__init__("Invalid implementation plan:\n" + "\n".join(self.issues))


class RevisionConflict(ImplementationError):
    def __init__(self, plan_id: str, expected: Any, current: int,
                 conflict_ref: str | None = None):
        self.plan_id = plan_id
        self.expected_revision = expected
        self.current_revision = current
        self.conflict_ref = conflict_ref
        message = (f"Plan {plan_id!r} is at revision {current}; "
                   f"the supplied base revision was {expected!r}.")
        if conflict_ref:
            message += (" Incoming content is preserved at " + conflict_ref +
                        ". Reconcile it with the current revision and save with that revision.")
        super().__init__(message)


def utc_now() -> str:
    return dt.datetime.now(dt.timezone.utc).isoformat(timespec="seconds").replace("+00:00", "Z")


def _fail_constant(value: str):
    raise ImplementationError(f"JSON contains a nonfinite number: {value}")


def _unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ImplementationError(f"Duplicate JSON object key: {key!r}")
        result[key] = value
    return result


def load_json(value: bytes | str, *, max_bytes: int = MAX_JSON_BYTES) -> dict:
    raw = value if isinstance(value, bytes) else value.encode("utf-8")
    if len(raw) > max_bytes:
        raise ImplementationError(f"Document exceeds {max_bytes} bytes.")
    try:
        result = json.loads(
            raw.decode("utf-8-sig"), parse_constant=_fail_constant,
            object_pairs_hook=_unique_object,
        )
    except (UnicodeError, json.JSONDecodeError, RecursionError) as exc:
        raise ImplementationError(f"Cannot read JSON: {exc}") from exc
    if not isinstance(result, dict):
        raise ImplementationError("The JSON root must be an object.")
    return result


def read_document(path: str | Path) -> dict:
    path = Path(path)
    with path.open("rb") as handle:
        raw = handle.read(MAX_JSON_BYTES + 1)
    return validate_plan(load_json(raw))


def canonical_bytes(document: Any) -> bytes:
    try:
        return json.dumps(document, ensure_ascii=False, sort_keys=True,
                          separators=(",", ":"), allow_nan=False).encode("utf-8")
    except (ValueError, TypeError, RecursionError, UnicodeError) as exc:
        raise ImplementationError(f"Document cannot be serialized safely: {exc}") from exc


def document_digest(document: dict) -> str:
    return hashlib.sha256(canonical_bytes(document)).hexdigest()


def json_text(document: Any) -> str:
    return json.dumps(document, ensure_ascii=False, indent=2,
                      sort_keys=True, allow_nan=False) + "\n"


def _safe_id(value: Any, name: str = "id") -> str:
    if not isinstance(value, str) or not ID_RE.fullmatch(value):
        raise ImplementationError(
            f"{name} must be 1–96 letters, digits, underscores or hyphens, "
            "beginning with a letter or digit."
        )
    return value


def _date(value: str) -> dt.date:
    if not isinstance(value, str) or not DATE_RE.fullmatch(value):
        raise ValueError("expected YYYY-MM-DD")
    return dt.date.fromisoformat(value)


def _timestamp(value: str) -> dt.datetime:
    if not isinstance(value, str) or "T" not in value:
        raise ValueError("expected an ISO timestamp with timezone")
    parsed = dt.datetime.fromisoformat(value.replace("Z", "+00:00"))
    if parsed.tzinfo is None or parsed.utcoffset() is None:
        raise ValueError("timestamp must include its timezone")
    return parsed


def _integer(value: Any, minimum: int = 0, maximum: int = SAFE_INTEGER) -> bool:
    return type(value) is int and minimum <= value <= maximum


def _number(value: Any) -> bool:
    return type(value) in (int, float) and math.isfinite(value)


def make_plan(plan_id: str, title: str, start_date: str, *,
              description: str = "", target_date: str | None = None,
              working_days: list[int] | None = None,
              holidays: list[str] | None = None) -> dict:
    now = utc_now()
    result = dict(
        schema=SCHEMA, id=plan_id, revision=0, title=title,
        description=description, start_date=start_date, currency="USD",
        working_days=list(working_days if working_days is not None else [1, 2, 3, 4, 5]),
        holidays=list(holidays or []), created_at=now, updated_at=now,
        **{name: [] for name in COLLECTIONS},
    )
    if target_date is not None:
        result["target_date"] = target_date
    return validate_plan(result)


def validate_plan(document: dict) -> dict:
    """Validate all core semantics and retain unknown JSON fields unchanged.

    IDs are unique within each typed collection. References always address the
    original ID in the specified collection; no label-based remapping occurs.
    """
    issues: list[str] = []
    if not isinstance(document, dict):
        raise ValidationError(["plan: expected an object"])

    def error(path, message):
        issues.append(f"{path}: {message}")

    def json_value(value, path="$", depth=0):
        if depth > 64:
            error(path, "JSON nesting exceeds 64 levels")
            return
        if value is None or type(value) in (bool, str):
            if isinstance(value, str):
                try:
                    value.encode("utf-8")
                except UnicodeError:
                    error(path, "invalid Unicode surrogate")
        elif type(value) is int:
            if abs(value) > SAFE_INTEGER:
                error(path, "integer is outside the interoperable safe range")
        elif type(value) is float:
            if not math.isfinite(value):
                error(path, "number must be finite")
        elif isinstance(value, list):
            for index, item in enumerate(value):
                json_value(item, f"{path}[{index}]", depth + 1)
        elif isinstance(value, dict):
            for key, item in value.items():
                if not isinstance(key, str):
                    error(path, "object keys must be strings")
                else:
                    json_value(key, path, depth + 1)
                    json_value(item, f"{path}.{key}", depth + 1)
        else:
            error(path, "value is not JSON compatible")

    def string(obj, key, path, required=True, nonempty=False):
        if key not in obj:
            if required:
                error(f"{path}.{key}", "is required")
            return
        value = obj[key]
        if not required and value is None:
            return
        if not isinstance(value, str) or (nonempty and not value.strip()):
            error(f"{path}.{key}", "expected " + ("a nonempty string" if nonempty else "a string"))

    def ident(obj, key, path, required=True):
        if key not in obj or obj[key] is None:
            if required:
                error(f"{path}.{key}", "is required")
            return
        try:
            _safe_id(obj[key], key)
        except ImplementationError as exc:
            error(f"{path}.{key}", str(exc))

    def date_field(obj, key, path, required=False, timestamp=False):
        if key not in obj or obj[key] is None:
            if required:
                error(f"{path}.{key}", "is required")
            return
        try:
            (_timestamp if timestamp else _date)(obj[key])
        except (ValueError, TypeError, OverflowError) as exc:
            error(f"{path}.{key}", str(exc))

    def numeric(obj, key, path, required=False, minimum=None, maximum=None):
        if key not in obj or obj[key] is None:
            if required:
                error(f"{path}.{key}", "is required")
            return
        value = obj[key]
        if (not _number(value) or (minimum is not None and value < minimum)
                or (maximum is not None and value > maximum)):
            error(f"{path}.{key}", "expected a finite number within the allowed range")

    def string_list(obj, key, path, required=True, unique=False, ids=False):
        if key not in obj:
            if required:
                error(f"{path}.{key}", "is required")
            return []
        value = obj[key]
        if not isinstance(value, list):
            error(f"{path}.{key}", "expected an array")
            return []
        result = []
        for index, item in enumerate(value):
            if not isinstance(item, str) or not item.strip():
                error(f"{path}.{key}[{index}]", "expected a nonempty string")
            else:
                if ids and not ID_RE.fullmatch(item):
                    error(f"{path}.{key}[{index}]", "invalid ID")
                result.append(item)
        if unique and len(result) != len(set(result)):
            error(f"{path}.{key}", "contains duplicate values")
        return result

    json_value(document)
    if issues:
        raise ValidationError(issues)
    if document.get("schema") != SCHEMA:
        error("schema", f"must equal {SCHEMA}")
    ident(document, "id", "plan")
    if not _integer(document.get("revision")):
        error("revision", "expected a nonnegative safe integer")
    string(document, "title", "plan", nonempty=True)
    string(document, "description", "plan")
    if document.get("currency") != "USD":
        error("currency", "must equal USD")
    date_field(document, "start_date", "plan", required=True)
    date_field(document, "target_date", "plan")
    for key in ("created_at", "updated_at"):
        date_field(document, key, "plan", required=True, timestamp=True)
    if isinstance(document.get("created_at"), str) and isinstance(document.get("updated_at"), str):
        try:
            if _timestamp(document["updated_at"]) < _timestamp(document["created_at"]):
                error("updated_at", "cannot precede created_at")
        except (ValueError, TypeError):
            pass
    if document.get("target_date") and document.get("start_date"):
        try:
            if _date(document["target_date"]) < _date(document["start_date"]):
                error("target_date", "cannot precede start_date")
        except (ValueError, TypeError):
            pass
    weekdays = document.get("working_days")
    if (not isinstance(weekdays, list) or not weekdays or
            any(not _integer(day, 1, 7) for day in weekdays) or
            len(weekdays) != len(set(day for day in weekdays if type(day) is int))):
        error("working_days", "expected unique ISO weekdays 1 through 7; at least one is required")
    holidays = string_list(document, "holidays", "plan", unique=True)
    for holiday in holidays:
        try:
            _date(holiday)
        except ValueError:
            error("holidays", f"invalid date {holiday!r}")

    rows: dict[str, list[dict]] = {}
    indexes: dict[str, dict[str, dict]] = {}
    for name in COLLECTIONS:
        entries = document.get(name)
        if not isinstance(entries, list):
            error(name, "expected an array")
            entries = []
        rows[name] = []
        indexes[name] = {}
        for index, row in enumerate(entries):
            path = f"{name}[{index}]"
            if not isinstance(row, dict):
                error(path, "expected an object")
                continue
            rows[name].append(row)
            ident(row, "id", path)
            row_id = row.get("id")
            if isinstance(row_id, str):
                if row_id in indexes[name]:
                    error(path + ".id", f"duplicate ID {row_id!r}")
                indexes[name][row_id] = row

    def reference(row, key, collection, path, required=False):
        ident(row, key, path, required)
        value = row.get(key)
        if value is not None and isinstance(value, str) and value not in indexes[collection]:
            error(path + "." + key, f"unknown {collection} ID {value!r}")

    for row in rows["source_links"]:
        path = f"source_links.{row.get('id', '?')}"
        string(row, "kind", path, nonempty=True)
        string(row, "label", path, nonempty=True)
        string(row, "reference", path, required=False, nonempty=True)

    for row in rows["candidates"]:
        path = f"candidates.{row.get('id', '?')}"
        string(row, "label", path, nonempty=True)
        numeric(row, "area_ha", path, minimum=0)
        if not isinstance(row.get("source"), (dict, str)) or not row.get("source"):
            error(path + ".source", "expected the original source reference or frozen snapshot object")
        if not isinstance(row.get("modeled_benefits"), list):
            error(path + ".modeled_benefits", "expected the retained array of modeled results")
        source = row.get("source")
        if isinstance(source, dict) and "source_link_id" in source:
            reference(source, "source_link_id", "source_links", path + ".source", required=True)
            link_id = source.get("source_link_id")
            link = indexes["source_links"].get(link_id) if isinstance(link_id, str) else None
            if link is not None:
                for source_key, link_key in (("source_digest", "source_digest"),
                                              ("source_id", "source_id"), ("source_kind", "kind")):
                    if source_key in source and link_key in link and source[source_key] != link[link_key]:
                        error(path + ".source." + source_key,
                              "does not match the retained original source link")

    for row in rows["tasks"]:
        path = f"tasks.{row.get('id', '?')}"
        for key in ("title", "phase", "assignee", "notes"):
            string(row, key, path, nonempty=(key == "title"))
        reference(row, "candidate_id", "candidates", path)
        if row.get("status") not in ("planned", "in_progress", "complete", "cancelled"):
            error(path + ".status", "expected planned, in_progress, complete or cancelled")
        if "duration_days" not in row or (row["duration_days"] is not None and
                                                       not _integer(row["duration_days"])):
            error(path + ".duration_days", "expected a nonnegative safe integer or null")
        numeric(row, "progress_pct", path, required=True, minimum=0, maximum=100)
        date_field(row, "start_not_before", path)
        dependencies = string_list(row, "depends_on", path, unique=True, ids=True)
        for dependency in dependencies:
            if dependency not in indexes["tasks"]:
                error(path + ".depends_on", f"unknown task ID {dependency!r}")
        string_list(row, "evidence_refs", path, unique=True)

    totals = dict(budget=0, commitment=0, actual=0)
    for row in rows["budget_lines"]:
        path = f"budget_lines.{row.get('id', '?')}"
        reference(row, "task_id", "tasks", path)
        string(row, "label", path, nonempty=True)
        kind = row.get("kind")
        if not isinstance(kind, str) or kind not in totals:
            error(path + ".kind", "expected budget, commitment or actual")
        amount = row.get("amount_minor")
        if not _integer(amount):
            error(path + ".amount_minor", "expected a nonnegative safe integer in USD cents")
        elif isinstance(kind, str) and kind in totals:
            totals[kind] += amount
        date_field(row, "date", path)
        string(row, "reference", path, required=False, nonempty=True)
    if any(total > SAFE_INTEGER for total in totals.values()):
        error("budget_lines", "a kind total exceeds the interoperable safe integer range")

    for row in rows["sites"]:
        path = f"sites.{row.get('id', '?')}"
        string(row, "label", path, nonempty=True)
        reference(row, "candidate_id", "candidates", path)
        reference(row, "source_ref", "source_links", path)
        numeric(row, "latitude", path, minimum=-90, maximum=90)
        numeric(row, "longitude", path, minimum=-180, maximum=180)
        if (row.get("latitude") is None) != (row.get("longitude") is None):
            error(path, "latitude and longitude must be supplied together")

    for row in rows["monitoring_plans"]:
        path = f"monitoring_plans.{row.get('id', '?')}"
        for key in ("title", "objective", "notes"):
            string(row, key, path, nonempty=(key == "title"))
        site_ids = string_list(row, "site_ids", path, unique=True, ids=True)
        for site_id in site_ids:
            if site_id not in indexes["sites"]:
                error(path + ".site_ids", f"unknown site ID {site_id!r}")
        string_list(row, "parameters", path, unique=True)
        for key in ("method_ref", "frequency"):
            string(row, key, path, required=False)

    for row in rows["visits"]:
        path = f"visits.{row.get('id', '?')}"
        reference(row, "site_id", "sites", path, required=True)
        reference(row, "monitoring_plan_id", "monitoring_plans", path)
        date_field(row, "planned_date", path)
        date_field(row, "visited_at", path, timestamp=True)
        string(row, "observer", path)
        string(row, "notes", path)
        string_list(row, "evidence_refs", path, unique=True)
        if row.get("status") not in ("planned", "complete", "cancelled"):
            error(path + ".status", "expected planned, complete or cancelled")
        if row.get("status") == "complete" and not row.get("visited_at"):
            error(path + ".visited_at", "a completed visit requires its actual timestamp")
        monitor_id = row.get("monitoring_plan_id")
        monitor = indexes["monitoring_plans"].get(monitor_id) if isinstance(monitor_id, str) else None
        if monitor and isinstance(monitor.get("site_ids"), list):
            if row.get("site_id") not in monitor["site_ids"]:
                error(path + ".site_id", "site is not in the referenced monitoring plan")

    for row in rows["activities"]:
        path = f"activities.{row.get('id', '?')}"
        reference(row, "visit_id", "visits", path, required=True)
        reference(row, "site_id", "sites", path, required=True)
        if row.get("kind") not in ("sample", "measurement", "inspection", "photo"):
            error(path + ".kind", "expected sample, measurement, inspection or photo")
        string(row, "notes", path)
        for key in ("sample_id", "method", "custody_ref"):
            string(row, key, path, required=False, nonempty=True)
        if "evidence_refs" in row:
            string_list(row, "evidence_refs", path, unique=True)
        date_field(row, "collected_at", path, timestamp=True)
        if row.get("kind") == "sample" and not row.get("sample_id"):
            error(path + ".sample_id", "a sample activity requires the original sample ID")
        visit_id = row.get("visit_id")
        visit = indexes["visits"].get(visit_id) if isinstance(visit_id, str) else None
        if visit and visit.get("site_id") != row.get("site_id"):
            error(path + ".site_id", "must equal the referenced visit's site_id")

    for row in rows["observations"]:
        path = f"observations.{row.get('id', '?')}"
        reference(row, "activity_id", "activities", path, required=True)
        for key in ("parameter", "original_text", "unit", "notes"):
            string(row, key, path, nonempty=(key == "parameter"))
        for key in ("basis", "fraction", "qualifier", "method", "qa_status"):
            string(row, key, path, required=False)
        result_type = row.get("result_type")
        if result_type not in ("numeric", "censored", "text", "missing"):
            error(path + ".result_type", "expected numeric, censored, text or missing")
        if "value" not in row:
            error(path + ".value", "must be explicitly present, using null when absent")
        value = row.get("value")
        if result_type == "numeric":
            if not _number(value):
                error(path + ".value", "numeric results require a finite numeric value")
            if (not isinstance(row.get("original_text"), str) or not row["original_text"].strip()):
                error(path + ".original_text", "preserve the original numeric result text")
        elif result_type in ("censored", "text", "missing") and value is not None:
            error(path + ".value", f"{result_type} results use null, preserving original_text and limits")
        if result_type in ("censored", "text") and (not isinstance(row.get("original_text"), str) or not row["original_text"].strip()):
            error(path + ".original_text", "must preserve the source result text")
        if result_type == "censored" and (not isinstance(row.get("qualifier"), str) or not row["qualifier"].strip()):
            error(path + ".qualifier", "censored results require the original qualifier")
        if result_type in ("numeric", "censored") and (not isinstance(row.get("unit"), str) or not row["unit"].strip()):
            error(path + ".unit", "numeric/censored results require the original unit; use 1 for dimensionless")
        for key in ("detection_limit", "quantitation_limit"):
            numeric(row, key, path, minimum=0)

    # Iterative Kahn traversal handles large plans without Python recursion limits.
    task_ids = set(indexes["tasks"])
    incoming = {}
    children = {task_id: [] for task_id in task_ids}
    for task_id, row in indexes["tasks"].items():
        deps = row.get("depends_on", [])
        deps = deps if isinstance(deps, list) else []
        valid_deps = {dep for dep in deps if isinstance(dep, str) and dep in task_ids}
        incoming[task_id] = len(valid_deps)
        for dep in valid_deps:
            children[dep].append(task_id)
    ready = [task_id for task_id in incoming if incoming[task_id] == 0]
    visited = 0
    while ready:
        task_id = ready.pop()
        visited += 1
        for child in children[task_id]:
            incoming[child] -= 1
            if incoming[child] == 0:
                ready.append(child)
    if visited != len(task_ids):
        error("tasks.depends_on", "dependency cycle involving " +
              ", ".join(sorted(task_id for task_id, count in incoming.items() if count)))

    if issues:
        raise ValidationError(issues)
    result = copy.deepcopy(document)
    if len(canonical_bytes(result)) >= MAX_JSON_BYTES:
        raise ValidationError([f"document: exceeds {MAX_JSON_BYTES} bytes"])
    return result


class ProjectCalendar:
    """ISO workday calendar with holiday-aware ordinal arithmetic."""
    def __init__(self, working_days: Iterable[int], holidays: Iterable[str]):
        self.working_days = frozenset(working_days)
        self.holidays = frozenset(_date(value) for value in holidays)
        self.holiday_ordinals = sorted(
            day.toordinal() for day in self.holidays
            if day.isoweekday() in self.working_days
        )

    def is_workday(self, day: dt.date) -> bool:
        return day.isoweekday() in self.working_days and day not in self.holidays

    def next_workday(self, day: dt.date) -> dt.date:
        while not self.is_workday(day):
            if day == dt.date.max:
                raise OverflowError("calendar extends beyond 9999-12-31")
            day += dt.timedelta(days=1)
        return day

    def _count(self, first: dt.date, last: dt.date) -> int:
        """Count eligible days in an inclusive interval."""
        if last < first:
            return 0
        length = (last - first).days + 1
        weeks, remainder = divmod(length, 7)
        count = weeks * len(self.working_days)
        count += sum(
            ((first.isoweekday() - 1 + offset) % 7 + 1) in self.working_days
            for offset in range(remainder)
        )
        count -= (bisect.bisect_right(self.holiday_ordinals, last.toordinal()) -
                  bisect.bisect_left(self.holiday_ordinals, first.toordinal()))
        return count

    def advance(self, start: dt.date, duration: int) -> tuple[dt.date, dt.date | None]:
        """Return exclusive finish boundary and last consumed working date."""
        start = self.next_workday(start)
        if duration == 0:
            return start, None
        low, high = start.toordinal(), dt.date.max.toordinal()
        if self._count(start, dt.date.max) < duration:
            raise OverflowError("duration extends beyond 9999-12-31")
        while low < high:
            middle = (low + high) // 2
            if self._count(start, dt.date.fromordinal(middle)) >= duration:
                high = middle
            else:
                low = middle + 1
        last = dt.date.fromordinal(low)
        if last == dt.date.max:
            raise OverflowError("exclusive finish extends beyond 9999-12-31")
        finish = self.next_workday(last + dt.timedelta(days=1))
        return finish, last


def schedule_plan(document: dict, as_of: str | None = None) -> dict:
    plan = validate_plan(document)
    as_of = as_of or dt.datetime.now(dt.timezone.utc).date().isoformat()
    try:
        selected_date = _date(as_of)
    except (TypeError, ValueError) as exc:
        raise ImplementationError(f"Invalid as_of date: {exc}") from exc
    calendar = ProjectCalendar(plan["working_days"], plan["holidays"])
    tasks = {row["id"]: row for row in plan["tasks"]}
    children = {task_id: [] for task_id in tasks}
    incoming = {task_id: len(row["depends_on"]) for task_id, row in tasks.items()}
    ready = [task_id for task_id in tasks if incoming[task_id] == 0]
    for task_id, row in tasks.items():
        for dependency in row["depends_on"]:
            children[dependency].append(task_id)
    results: dict[str, dict] = {}
    issues: list[dict] = []
    for task_id in ready:
        task = tasks[task_id]
        row = dict(
            id=task_id, title=task["title"], status=task["status"],
            start=None, finish_exclusive=None, last_work_date=None,
            duration_days=task["duration_days"], schedule_state="scheduled",
            issue_codes=[], overdue=False,
        )

        def issue(code: str, message: str):
            row["issue_codes"].append(code)
            issues.append(dict(task_id=task_id, code=code, message=message))

        blocked = [
            dependency for dependency in task["depends_on"]
            if results[dependency]["finish_exclusive"] is None
        ]
        cancelled = [dependency for dependency in task["depends_on"]
                     if tasks[dependency]["status"] == "cancelled"]
        if cancelled and task["status"] != "cancelled":
            issue("cancelled_dependency", "Predecessor(s) cancelled: " + ", ".join(cancelled) +
                  ". Review whether this dependency still belongs in the plan.")
        if blocked:
            row["schedule_state"] = "blocked_unknown"
            issue("dependency_finish_unknown",
                  "Enter predecessor duration or resolve its calendar range for: " + ", ".join(blocked))
        else:
            earliest = max(
                [_date(plan["start_date"])] +
                ([_date(task["start_not_before"])] if task.get("start_not_before") else []) +
                [_date(results[dependency]["finish_exclusive"])
                 for dependency in task["depends_on"]]
            )
            try:
                start = calendar.next_workday(earliest)
                row["start"] = start.isoformat()
                if task["duration_days"] is None:
                    row["schedule_state"] = "unknown_duration"
                    issue("duration_unknown", "Enter a duration to calculate the finish boundary.")
                else:
                    finish, last = calendar.advance(start, task["duration_days"])
                    row["finish_exclusive"] = finish.isoformat()
                    row["last_work_date"] = last.isoformat() if last else None
                    if task["status"] not in ("complete", "cancelled"):
                        row["overdue"] = (
                            start < selected_date if task["duration_days"] == 0
                            else finish <= selected_date
                        )
                    if plan.get("target_date"):
                        due = last or start
                        if due > _date(plan["target_date"]):
                            issue("after_project_target",
                                  f"Task's last planned work date is after target {plan['target_date']}.")
            except OverflowError as exc:
                row["schedule_state"] = "calendar_overflow"
                issue("calendar_overflow", str(exc))
        if (task["status"] == "complete" and task["progress_pct"] != 100) or (
                task["status"] == "planned" and task["progress_pct"] != 0):
            issue("status_progress_mismatch",
                  "Status and progress differ; both original values have been retained.")
        results[task_id] = row
        for child in children[task_id]:
            incoming[child] -= 1
            if incoming[child] == 0:
                ready.append(child)
    active = [results[task_id] for task_id in tasks if tasks[task_id]["status"] != "cancelled"]
    known_finishes = [row["finish_exclusive"] for row in active if row["finish_exclusive"]]
    return dict(
        as_of=as_of, calendar=dict(
            working_days=list(plan["working_days"]), holidays=list(plan["holidays"])
        ),
        tasks=[results[row["id"]] for row in plan["tasks"]], issues=issues,
        critical_finish_exclusive=(
            max(known_finishes) if known_finishes and all(row["finish_exclusive"] for row in active)
            else None
        ),
        latest_known_finish_exclusive=max(known_finishes) if known_finishes else None,
        unknown_task_count=sum(row["finish_exclusive"] is None for row in active),
    )


def summarize_plan(document: dict, as_of: str | None = None) -> dict:
    plan = validate_plan(document)
    schedule = schedule_plan(plan, as_of)
    by_task = {}
    totals = dict(budget=0, commitment=0, actual=0)
    for line in plan["budget_lines"]:
        totals[line["kind"]] += line["amount_minor"]
        key = line.get("task_id") or ""
        values = by_task.setdefault(key, dict(budget=0, commitment=0, actual=0))
        values[line["kind"]] += line["amount_minor"]
    task_counts = {status: sum(task["status"] == status for task in plan["tasks"])
                   for status in ("planned", "in_progress", "complete", "cancelled")}
    visit_counts = {status: sum(visit["status"] == status for visit in plan["visits"])
                   for status in ("planned", "complete", "cancelled")}
    due_visits = [
        visit["id"] for visit in plan["visits"]
        if visit["status"] == "planned" and visit.get("planned_date")
        and visit["planned_date"] < schedule["as_of"]
    ]
    planned_active = visit_counts["planned"] + visit_counts["complete"]
    return dict(
        schema="upstate.implementation-summary/v1",
        plan_id=plan["id"], revision=plan["revision"], title=plan["title"],
        as_of=schedule["as_of"], currency=plan["currency"],
        budget_minor=totals["budget"], commitment_minor=totals["commitment"],
        actual_minor=totals["actual"], budget_by_task=by_task,
        task_counts=task_counts, overdue_task_ids=[
            row["id"] for row in schedule["tasks"] if row["overdue"]
        ],
        visit_counts=visit_counts, overdue_visit_ids=due_visits,
        visit_completion_pct=(100 * visit_counts["complete"] / planned_active
                              if planned_active else None),
        observation_counts={
            kind: sum(row["result_type"] == kind for row in plan["observations"])
            for kind in ("numeric", "censored", "text", "missing")
        },
        site_count=len(plan["sites"]), activity_count=len(plan["activities"]),
        schedule=schedule,
    )

