"""Carry exact saved Monitoring campaigns into native Implementation fieldwork.

The Monitoring and Implementation stores remain authoritative. Each source
edition is frozen, its complete original monitoring packet is a managed plan
attachment, and subsequent imports merge only unchanged generated fields.
"""
from __future__ import annotations

from copy import deepcopy
import hashlib
import json
from pathlib import Path

from .implementation import ImplementationStore
from .implementation_schema import make_plan, validate_plan, document_digest
from .monitoring_common import ContractError, canonical_bytes, digest, file_sha256, held
from .monitoring_sources import source_export_members
from .monitoring_packet import add_member, bytes_member, file_member, retain_packet

FORMAT = "upstate.monitoring-fieldwork/v1"
MAPPED = ("sites", "monitoring_plans", "visits", "tasks", "activities", "budget_lines")


def _id(kind, value):
    return kind + "_" + digest(value)


def _field_digest(row, key):
    return digest({"present": key in row, "value": row.get(key)})


def _selection(service, campaign_id, revision_id):
    history = service.history(campaign_id)
    selected = next((row for row in history if row["id"] == revision_id), None)
    if selected is None:
        raise ContractError("Select an original revision of this monitoring campaign")
    plan = service.get("plans", selected["plan_id"])
    network = service.get("networks", selected["network_id"])
    if plan["network_id"] != network["id"] or plan["status"] not in {"optimal", "feasible"}:
        raise ContractError("Fieldwork requires the campaign's retained feasible design")
    service.verify_sources(network)
    events = [service.get("events", key) for key in selected["event_ids"]]
    retained_history = history[:history.index(selected) + 1]
    plan_ids = {row["plan_id"] for row in retained_history + events}
    retained_plans = {key: service.get("plans", key) for key in sorted(plan_ids)}
    network_ids = {row["network_id"] for row in retained_history}
    network_ids.update(row["network_id"] for row in retained_plans.values())
    retained_networks = {key: service.get("networks", key) for key in sorted(network_ids)}
    for original in retained_networks.values():
        service.verify_sources(original)
    from .monitoring_field_return import source_binding
    return_cache = {}
    returned = {event["id"]: binding for event in events
                if (binding := source_binding(service.workspace, event, return_cache)) is not None}
    return {"revision": selected, "plan": plan, "network": network,
            "events": events, "fieldwork_returns": returned, "history": retained_history,
            "retained_plans": retained_plans, "retained_networks": retained_networks}


def _packet(workspace, selected):
    """Retain the complete original packet while keeping native bodies on disk."""
    files = {}
    for name in ("revision", "plan", "network", "events", "history"):
        add_member(files, name + ".json", bytes_member(canonical_bytes(selected[name])))
    for key, original in selected["retained_plans"].items():
        add_member(files, "designs/" + key + ".json", bytes_member(canonical_bytes(original)))
    for key, original in selected["retained_networks"].items():
        add_member(files, "networks/" + key + ".json", bytes_member(canonical_bytes(original)))
        for label, binding in original["source_bindings"].items():
            if binding:
                for name, member in source_export_members(workspace, label, binding):
                    add_member(files, "network_sources/" + key + "/" + name, member)
    retained_returns = {binding["request_id"]: binding
                        for binding in selected.get("fieldwork_returns", {}).values()}
    for binding in retained_returns.values():
        for name, original in binding["source_files"].items():
            original = Path(original)
            add_member(files, "fieldwork_returns/" + binding["request_id"] + "/" + name,
                       file_member(original, original.stat().st_size, file_sha256(original)))
    manifest = canonical_bytes({
        "schema": FORMAT, "campaign_id": selected["revision"]["campaign_id"],
        "source_revision_id": selected["revision"]["id"],
        "files": [{"path": name, "bytes": member["bytes"], "sha256": member["sha256"]}
                  for name, member in sorted(files.items())]})
    add_member(files, "manifest.json", bytes_member(manifest))
    packet = (workspace.root / "monitoring_fieldwork" / selected["revision"]["id"]
              / "monitoring-field-package.zip")
    return retain_packet(packet, files)

def _rows(selected, source_id):
    revision, plan, network = (selected[name] for name in ("revision", "plan", "network"))
    campaign_id = revision["campaign_id"]
    station_index = {row["id"]: row for row in network["stations"]}
    result = {name: [] for name in MAPPED}
    site_ids = {}
    def add_site(catchment, station_id):
        site_id = _id("site", [campaign_id, network["id"], catchment, station_id])
        station = station_index.get(station_id) if station_id else None
        if station_id and (station is None or station["huc_id"] != catchment):
            raise ContractError("Retain the campaign's original station assignment")
        row = {"id": site_id, "label": station_id or catchment, "source_ref": source_id,
               "monitoring_catchment_id": catchment, "monitoring_station_id": station_id,
               "geometry_role": "original_source_station" if station else "source_catchment_search_area"}
        if station is not None:
            point = station["geometry"]
            if point["type"] != "Point":
                raise ContractError("Field station coordinates need an original source point")
            row.update(longitude=point["coordinates"][0], latitude=point["coordinates"][1])
        if not any(value["id"] == site_id for value in result["sites"]):
            result["sites"].append(row)
        return site_id
    for catchment in plan["selected_ids"]:
        site_ids[catchment] = add_site(catchment, revision["site_bindings"].get(catchment))
    monitoring_id = _id("monitor", [campaign_id, plan["id"]])
    result["monitoring_plans"].append({
        "id": monitoring_id, "title": revision["title"],
        "objective": "Execute the retained monitoring campaign and its original field calendar.",
        "notes": "Source coverage mode: " + plan["coverage_mode"] + ". " +
                 plan["calendar"]["scheduling_basis"],
        "site_ids": list(site_ids.values()), "parameters": [],
        "method_ref": source_id, "frequency": "Original saved campaign rounds",
        "monitoring_design_id": plan["id"], "source_revision_id": revision["id"]})
    recent = {}
    for event in selected["events"]:
        if event["plan_id"] == plan["id"] and event["status"] != "note":
            recent[event["visit_key"]] = event
    visit_ids = {}
    for original in plan["calendar"]["visits"]:
        key = original["visit_key"]
        visit_id = visit_ids[key] = _id("visit", [campaign_id, plan["id"], key])
        event = recent.get(key)
        native_status = event["status"] if event else "planned"
        status = {"collected": "complete", "cancelled": "cancelled"}.get(native_status, "planned")
        notes = ("Original local time " + original["start_local"] + "–" + original["finish_local"] +
                 "; crew " + str(original["crew"]) + "; round " + str(original["round"]) +
                 ". Original monitoring status: " + native_status + ".")
        if event and event.get("note"):
            notes += " " + event["note"]
        actual_site = (add_site(original["site_id"], event["station_id"])
                       if event and event["status"] == "collected" else site_ids[original["site_id"]])
        visit = {"id": visit_id, "site_id": actual_site,
                 "monitoring_plan_id": monitoring_id, "planned_date": original["date"],
                 "observer": "", "notes": notes, "evidence_refs": [source_id], "status": status,
                 "monitoring_visit_key": key, "source_status": native_status,
                 "original_calendar": deepcopy(original),
                 "source_event_id": event["id"] if event else None}
        if status == "complete":
            visit["visited_at"] = event["occurred_at"]
        result["visits"].append(visit)
        result["tasks"].append({
            "id": _id("task", [campaign_id, plan["id"], key]), "title": "Monitoring visit " + key,
            "phase": "Monitoring", "assignee": "Crew " + str(original["crew"]),
            "notes": notes, "duration_days": None, "start_not_before": original["date"],
            "status": status, "progress_pct": 100 if status == "complete" else 0,
            "depends_on": [], "evidence_refs": [source_id], "monitoring_visit_id": visit_id})
    for event in selected["events"]:
        # Historic design events remain in their exact packet; the active design
        # maps only source-backed collected samples to current fieldwork visits.
        if event["plan_id"] != plan["id"] or event["status"] != "collected":
            continue
        if event["visit_key"] not in visit_ids or not event.get("sample_id"):
            raise ContractError("An original collected event needs its saved visit and sample ID")
        returned = selected.get("fieldwork_returns", {}).get(event["id"])
        activity_id = (returned["activity"]["id"] if returned and returned["activity"] is not None
                       else _id("sample", [campaign_id, event["id"]]))
        generated = {
            "id": activity_id,
            "visit_id": visit_ids[event["visit_key"]],
            "site_id": add_site(event["site_id"], event["station_id"]),
            "kind": "sample", "sample_id": event["sample_id"], "collected_at": event["occurred_at"],
            "notes": event.get("note", ""), "source_event_id": event["id"],
            "source_values": deepcopy(event.get("values", {})), "source_ref": source_id,
            "monitoring_station_id": event.get("station_id")}
        prior_activity = next((row for row in result["activities"] if row["id"] == activity_id), None)
        if prior_activity is None:
            result["activities"].append(generated)
        else:
            prior_activity.clear()
            prior_activity.update(generated)
    result["monitoring_plans"][0]["site_ids"] = [row["id"] for row in result["sites"]]
    # Activities retain the actual event station. A separate historic visit keeps
    # an earlier station binding when a later event on the same scheduled slot
    # names another point.
    visits_by_id = {row["id"]: row for row in result["visits"]}
    for activity in result["activities"]:
        visit = visits_by_id[activity["visit_id"]]
        if visit["site_id"] != activity["site_id"]:
            historical = deepcopy(visit)
            historical.update(id=_id("visit_event", activity["source_event_id"]),
                              site_id=activity["site_id"], status="complete",
                              visited_at=activity["collected_at"],
                              source_event_id=activity["source_event_id"],
                              source_status="collected", notes=activity["notes"])
            result["visits"].append(historical)
            activity["visit_id"] = historical["id"]
    if plan["cost"]["currency"] != "USD":
        raise ContractError("The Implementation planning budget requires original USD cents")
    result["budget_lines"].append({
        "id": _id("budget", campaign_id), "label": "Original monitoring design planning cost",
        "kind": "budget", "amount_minor": plan["cost"]["total_cents"],
        "reference": source_id, "monitoring_design_id": plan["id"],
        "planning_cost": deepcopy(plan["cost"])})
    return result



def _reconcile_references(document, before, previous, managed, conflicts):
    """Preserve local deletions and edits as a coherent fieldwork graph."""
    prior = {name: {row["id"]: row for row in before[name]} for name in MAPPED}
    def index(name):
        return {row["id"]: row for row in document[name]}
    def defer(name, row, reason):
        old = prior[name].get(row["id"])
        if old == row:
            return
        conflicts.append({"collection": name, "id": row["id"], "field": None,
                          "reason": reason, "incoming": deepcopy(row)})
        if old is None:
            document[name].remove(row)
            managed[name].pop(row["id"], None)
        else:
            row.clear()
            row.update(deepcopy(old))
            if row["id"] in previous.get(name, {}):
                managed[name][row["id"]] = deepcopy(previous[name][row["id"]])
    sites, monitors = index("sites"), index("monitoring_plans")
    for row in list(document["visits"]):
        monitor_id = row.get("monitoring_plan_id")
        if (row["site_id"] not in sites or (monitor_id and monitor_id not in monitors)
                or (row.get("status") == "complete" and not row.get("visited_at"))):
            defer("visits", row, "The source change depends on a parent or completion field changed in fieldwork")
        elif (monitor_id and monitor_id not in managed["monitoring_plans"]
              and row["site_id"] not in monitors[monitor_id]["site_ids"]):
            defer("visits", row, "The source change falls outside the locally selected monitoring plan")
    visits = index("visits")
    # Existing sample locations protect their visit. Restore an accepted source
    # visit update before considering its dependent incoming sample changes.
    for row in document["activities"]:
        if row["id"] in prior["activities"]:
            retained_visit = visits.get(row["visit_id"])
            if retained_visit and retained_visit["site_id"] == row["site_id"] and row["site_id"] in sites:
                continue
            old = prior["activities"][row["id"]]
            visit = visits.get(old["visit_id"])
            if visit and visit["site_id"] != old["site_id"]:
                defer("visits", visit, "Preserved the original site of an existing fieldwork activity")
    visits = index("visits")
    for row in list(document["activities"]):
        visit = visits.get(row["visit_id"])
        if not visit or row["site_id"] not in sites or visit["site_id"] != row["site_id"]:
            defer("activities", row, "The source sample depends on a visit or site changed in fieldwork")
    for row in list(document["tasks"]):
        if row.get("monitoring_visit_id") and row["monitoring_visit_id"] not in visits:
            defer("tasks", row, "The source task depends on a visit removed in fieldwork")
    # Keep user-added members while admitting the actual retained visit sites.
    # The incoming source membership remains in the conflict and frozen packet.
    for row in document["monitoring_plans"]:
        if row["id"] not in managed["monitoring_plans"]:
            continue
        fields = managed["monitoring_plans"][row["id"]]
        was_managed = _field_digest(row, "site_ids") == fields.get("site_ids")
        members = [key for key in row["site_ids"] if key in sites]
        for visit in document["visits"]:
            if visit.get("monitoring_plan_id") == row["id"] and visit["site_id"] not in members:
                members.append(visit["site_id"])
        if members != row["site_ids"]:
            conflicts.append({"collection": "monitoring_plans", "id": row["id"],
                              "field": "site_ids", "reason": "Reconciled membership with retained fieldwork visits",
                              "incoming": deepcopy(row["site_ids"])})
            row["site_ids"] = members
            if was_managed:
                fields["site_ids"] = _field_digest(row, "site_ids")


def _merge(document, incoming, source_revision_id, *, fieldwork_baselines=None):
    """Apply source changes per field only when the fieldwork value is unchanged."""
    origin = document.get("monitoring_origin", {})
    previous = origin.get("managed_fields", {})
    managed, conflicts = {}, []
    before = {name: deepcopy(document[name]) for name in MAPPED}
    for collection in MAPPED:
        rows = document[collection]
        by_id = {row["id"]: row for row in rows}
        managed[collection] = deepcopy(previous.get(collection, {}))
        for new in incoming[collection]:
            old_fields = previous.get(collection, {}).get(new["id"])
            current = by_id.get(new["id"])
            if current is None:
                if old_fields is not None:
                    conflicts.append({"collection": collection, "id": new["id"],
                                      "field": None, "reason": "Removed in fieldwork",
                                      "incoming": deepcopy(new)})
                    continue
                current = deepcopy(new)
                rows.append(current)
                by_id[current["id"]] = current
                managed[collection][current["id"]] = {
                    key: _field_digest(current, key) for key in current}
                continue
            if old_fields is None:
                returned = (fieldwork_baselines or {}).get(current["id"]) if collection == "activities" else None
                if returned is None:
                    raise ContractError("An existing fieldwork row has a different source identity")
                # Only a byte-bound original return may join its existing local
                # activity. Track generated fields; keep its other field inputs.
                old_fields = {key: _field_digest(returned, key) for key in new}
                managed[collection][current["id"]] = deepcopy(old_fields)
            saved_fields = managed[collection][current["id"]]
            for key in set(old_fields) | set(new):
                actual = _field_digest(current, key)
                proposed = _field_digest(new, key)
                if actual == proposed:
                    saved_fields[key] = proposed
                elif actual == old_fields.get(key) or (key not in old_fields and key not in current):
                    if key in new:
                        current[key] = deepcopy(new[key])
                    else:
                        current.pop(key, None)
                    saved_fields[key] = proposed
                else:
                    conflicts.append({"collection": collection, "id": new["id"], "field": key,
                                      "reason": "Edited in fieldwork", "present": key in new,
                                      "incoming": deepcopy(new.get(key))})
    _reconcile_references(document, before, previous, managed, conflicts)
    # Retire after all incoming rows have been merged. Local dependencies and
    # additional fields make a generated row retained work.
    for collection in ("tasks", "visits"):
        rows = document[collection]
        wanted = {row["id"] for row in incoming[collection]}
        if collection == "tasks":
            referenced = {key for row in document["tasks"] for key in row.get("depends_on", [])}
            referenced.update(row.get("task_id") for row in document["budget_lines"])
        else:
            referenced = {row["visit_id"] for row in document["activities"]}
            referenced.update(row.get("monitoring_visit_id") for row in document["tasks"])
        for current in list(rows):
            fields = previous.get(collection, {}).get(current["id"])
            if (fields and current["id"] not in wanted and current.get("status") == "planned"
                    and current["id"] not in referenced
                    and set(current) == {key for key, value in fields.items()
                                         if value != _field_digest({}, key)}
                    and all(_field_digest(current, key) == value for key, value in fields.items())):
                document.setdefault("monitoring_superseded_rows", []).append({
                    "collection": collection, "source_revision_id": source_revision_id,
                    "row": deepcopy(current)})
                rows.remove(current)
                managed[collection].pop(current["id"], None)
    return managed, conflicts


def _merge_calendar(document, source, previous):
    config = source["plan"]["configuration"]["calendar"]
    proposed = {"title": source["revision"]["title"], "start_date": config["start_date"],
                "target_date": config["end_date"],
                "working_days": sorted(set(day + 1 for day in config.get("weekdays", [0, 1, 2, 3, 4]))),
                "holidays": sorted(set(config.get("blackout_dates", [])))}
    fields = deepcopy(previous.get("calendar_fields", {}))
    prior_dates = {key: deepcopy(document.get(key)) for key in ("start_date", "target_date")}
    conflicts = []
    for key, value in proposed.items():
        incoming = _field_digest(proposed, key)
        actual = _field_digest(document, key)
        if not previous or actual == incoming or actual == fields.get(key):
            document[key] = deepcopy(value)
            fields[key] = incoming
        else:
            conflicts.append({"collection": "plan", "id": document["id"], "field": key,
                              "reason": "Edited in fieldwork", "incoming": deepcopy(value)})
    if document.get("target_date") and document["target_date"] < document["start_date"]:
        conflicts.append({"collection": "plan", "id": document["id"],
                          "field": "date_range", "reason": "Preserved the valid fieldwork calendar range",
                          "incoming": {key: proposed[key] for key in prior_dates}})
        for key, value in prior_dates.items():
            document[key] = value
            if key in previous.get("calendar_fields", {}):
                fields[key] = previous["calendar_fields"][key]
            else:
                fields.pop(key, None)
    return fields, conflicts


def receive(service, *, campaign_id, expected_revision_id, operation_id):
    """One queued operation; replay resumes the same source edition and attachment."""
    if not isinstance(operation_id, str) or not operation_id:
        raise ContractError("Retain the original handoff operation ID")
    with held(service.lock, blocking=False):
        selected = _selection(service, campaign_id, expected_revision_id)
        revision, source_plan = selected["revision"], selected["plan"]
        plan_id = _id("monitoring", campaign_id)
        source_id = _id("campaign", revision["id"])
        store = ImplementationStore(service.workspace)
        retained = store.history(plan_id) if (store.base / plan_id).is_dir() else []
        current = store.get(plan_id) if retained else None
        if current and current.get("monitoring_origin", {}).get("campaign_id") != campaign_id:
            raise ContractError("The selected fieldwork plan belongs to another campaign")
        existing = next((row for row in (current or {}).get("source_links", [])
                         if row["id"] == source_id), None)
        actor = "monitoring.fieldwork:" + revision["id"]
        if existing:
            packet_sha = existing["snapshot"]["packet"]["sha256"]
            packet_bytes = existing["snapshot"]["packet"]["bytes"]
        else:
            packet = _packet(service.workspace, selected)
            packet_sha, packet_bytes = packet["sha256"], packet["bytes"]
            calendar = source_plan["configuration"]["calendar"]
            document = deepcopy(current) if current else make_plan(
                plan_id, revision["title"], calendar["start_date"],
                target_date=calendar["end_date"], description="Fieldwork from the original saved monitoring campaign.",
                working_days=sorted(set(day + 1 for day in calendar.get("weekdays", [0, 1, 2, 3, 4]))),
                holidays=sorted(set(calendar.get("blackout_dates", []))))
            snapshot = {"campaign_revision": deepcopy(revision), "design_id": source_plan["id"],
                        "network_id": selected["network"]["id"],
                        "source_bindings": deepcopy(selected["network"]["source_bindings"]),
                        "packet": {"sha256": packet_sha, "bytes": packet_bytes},
                        "calendar_basis": source_plan["calendar"]["scheduling_basis"]}
            document["source_links"].append({
                "id": source_id, "kind": "monitoring_campaign", "label": revision["title"] +
                " · source revision " + str(revision["revision"]),
                "reference": "monitoring_revisions/" + revision["id"] + ".json",
                "source_id": revision["id"], "source_digest": digest(snapshot),
                "source_schema": revision["schema"], "snapshot": snapshot})
            origin = document.get("monitoring_origin", {})
            if revision["revision"] >= origin.get("campaign_revision", 0):
                returned_baselines = {binding["activity"]["id"]: binding["activity"]
                                      for binding in selected.get("fieldwork_returns", {}).values()
                                      if binding["activity"] is not None}
                managed, conflicts = _merge(document, _rows(selected, source_id), revision["id"],
                                            fieldwork_baselines=returned_baselines)
                calendar_fields, calendar_conflicts = _merge_calendar(document, selected, origin)
                conflicts.extend(calendar_conflicts)
                document["monitoring_origin"] = {
                    "schema": FORMAT, "campaign_id": campaign_id, "campaign_revision": revision["revision"],
                    "source_revision_id": revision["id"], "design_id": source_plan["id"],
                    "network_id": selected["network"]["id"],
                    "managed_fields": managed, "calendar_fields": calendar_fields,
                    "preserved_fieldwork_changes": conflicts}
            document = validate_plan(document)
            current = (store.save(document, current["revision"], actor=actor) if current else
                       store.create(document, actor=actor))
        attachment = next((row for row in current["source_links"]
                           if row.get("kind") == "local_file" and row.get("sha256") == packet_sha), None)
        if attachment is None:
            packet = service.root / "monitoring_fieldwork" / revision["id"] / "monitoring-field-package.zip"
            if not packet.is_file() or packet.stat().st_size != packet_bytes:
                raise ContractError("Resume with the original retained monitoring field package")
            if file_sha256(packet) != packet_sha:
                raise ContractError("The original monitoring field package changed")
            attached = store.attach_file(plan_id, packet, current["revision"], actor=actor,
                                         label="Original monitoring campaign revision " + str(revision["revision"]))
            current, attachment = attached["plan"], attached["source_link"]
        attached_path = (service.root / attachment["reference"]).resolve(strict=True)
        if (not attached_path.is_relative_to((store.base / plan_id / "attachments").resolve())
                or attached_path.stat().st_size != packet_bytes
                or file_sha256(attached_path) != packet_sha):
            raise ContractError("The retained fieldwork source attachment changed")
        origin = current["monitoring_origin"]
        return {"schema": FORMAT, "plan_id": plan_id, "revision": current["revision"],
                "campaign_id": campaign_id, "source_revision_id": revision["id"],
                "campaign_revision": revision["revision"],
                "active_source_revision_id": origin["source_revision_id"],
                "counts": {name: len(current[name]) for name in MAPPED},
                "preserved_fieldwork_changes": deepcopy(origin.get("preserved_fieldwork_changes", [])),
                "attachment": deepcopy(attachment), "document_digest": document_digest(current)}

files.model/monitoring_native_observations.py:
"""Project saved original observations into ordinary Monitoring source context.

Read-only preview retains the original import and explicit qualifier meanings.
Preparation uses Workspace.import_sources and the existing observed-context store.
No flow, station, annual mass, concentration trend or native model is generated.
"""
from __future__ import annotations

import argparse
from collections import Counter
from copy import deepcopy
from datetime import date
import hashlib
import json
import math
from pathlib import Path
import re
import tempfile

from .common import identifier, relative_file, verify_file
from .monitoring_common import ContractError, canonical_bytes, digest, file_sha256
from . import monitoring_observed_context as observed

EDITION = "upstate.native-observation-monitoring-context/v1"
OPTIONAL_COLUMNS = (
    "activity", "fraction", "depth", "depth_unit", "method_authority", "value_type",
    "weight_basis", "time_basis", "temperature_basis", "particle_size_basis",
    "project", "time", "timezone", "reporting_limit", "reporting_limit_unit", "comment",
    "activity_type", "sample_media", "sample_media_subdivision", "method_name",
    "method_specification", "organization_id", "analytical_fraction",
    "result_depth", "result_depth_unit",
)
DEFAULT_INTERPRETATION = {
    "columns": {}, "below_qualifiers": ["<", "<="], "above_qualifiers": [">", ">="],
    "numeric_qualifiers": [""], "nonnegative": False, "use_limit_unit_when_missing": False,
}
SELECTION_KEYS = {"observation_id", "network_id", "plan_id", "campaign_id",
                  "station_mapping", "title", "interpretation"}
INLINE_LIMIT = re.compile(r"^\s*(<=|>=|<|>|≤|≥)\s*([+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?)\s*$")
FLOW_UNAVAILABLE = {
    "status": "not_received",
    "reason": "No daily-flow series was selected for this native observation context.",
}


def _text(value, label, *, empty=False):
    if not isinstance(value, str) or (not empty and not value.strip()):
        raise ContractError(label + " must be original text")
    return value


def _number(value, label):
    if isinstance(value, bool):
        raise ContractError(label + " must be finite")
    try:
        result = float(value)
    except (ValueError, TypeError, OverflowError) as error:
        raise ContractError(label + " must be finite") from error
    if not math.isfinite(result):
        raise ContractError(label + " must be finite")
    return result


def interpretation(value, columns):
    if not isinstance(value, dict) or set(value) - set(DEFAULT_INTERPRETATION):
        raise ContractError("Choose the explicit original-column and qualifier interpretation")
    result = deepcopy(DEFAULT_INTERPRETATION)
    result.update(deepcopy(value))
    if any(type(result[key]) is not bool for key in ("nonnegative", "use_limit_unit_when_missing")):
        raise ContractError("Nonnegative support and missing-unit choices must be explicit booleans")
    selected = result["columns"]
    if not isinstance(selected, dict) or set(selected) - set(OPTIONAL_COLUMNS):
        raise ContractError("Optional mapping contains an unsupported context field")
    if any(not isinstance(column, str) or (column and column not in columns) for column in selected.values()):
        raise ContractError("Optional mappings must select exact retained original column names")
    groups = []
    for key in ("below_qualifiers", "above_qualifiers", "numeric_qualifiers"):
        values = result[key]
        if not isinstance(values, list) or any(not isinstance(token, str) or token != token.strip() for token in values):
            raise ContractError("Qualifier meanings must list exact retained tokens without surrounding whitespace")
        if len(values) != len(set(values)):
            raise ContractError("A qualifier meaning repeats")
        result[key] = sorted(values)
        groups.append(set(values))
    if any(groups[a] & groups[b] for a in range(3) for b in range(a + 1, 3)):
        raise ContractError("Each qualifier must have only one explicit meaning")
    return result


def _native(workspace, observation_id):
    key = identifier(observation_id)
    value = workspace._get("observations", key)
    if (value.get("schema") != "upstate.observations/v1"
            or not isinstance(value.get("metadata"), dict)
            or not isinstance(value.get("rows"), list)
            or any(not isinstance(row, dict) for row in value["rows"])
            or not isinstance(value.get("columns"), list)
            or any(not isinstance(column, str) for column in value["columns"])
            or len(value["columns"]) != len(set(value["columns"]))):
        raise ContractError("The native observation record lacks its original rows, columns or metadata")
    original = value.get("original")
    if not isinstance(original, dict) or not original.get("object"):
        raise ContractError("The native observation record lacks its retained original file")
    verify_file(workspace.root, {**original, "path": original["object"]})
    record = relative_file(workspace.root, "observations/" + key + ".json")
    return value, record


def catalog(workspace):
    values = []
    for path in sorted((workspace.root / "observations").glob("*.json")):
        source, _ = _native(workspace, path.stem)
        metadata = source.get("metadata", {})
        rows = source["rows"]
        values.append({
            "observation_id": source["id"], "title": metadata.get("title", source["id"]),
            "rows": len(rows), "columns": deepcopy(source["columns"]),
            "stations": sorted({str(row.get("station_id", "")) for row in rows}),
            "qualifiers": sorted({str(row.get("qualifier") or "").strip() for row in rows}),
            "source_uri": metadata.get("source_uri"),
            "value_basis": metadata.get("value_basis"),
            "original_mapping": deepcopy(metadata.get("columns", {})),
            "interpretation": deepcopy(DEFAULT_INTERPRETATION),
            "optional_columns": list(OPTIONAL_COLUMNS),
        })
    return {"observations": values}


def _selection(workspace, selection, source):
    if not isinstance(selection, dict) or set(selection) - SELECTION_KEYS:
        raise ContractError("Select an original observation, native network and explicit interpretation")
    title = _text(selection.get("title"), "Context title").strip()
    mapping = selection.get("station_mapping", {})
    if not isinstance(mapping, dict) or any(not isinstance(k, str) or not k or
            not isinstance(v, str) or not v for k, v in mapping.items()):
        raise ContractError("Station mapping must use exact source and saved network IDs")
    network, plan, campaign = observed._selection(
        workspace, selection.get("network_id"), selection.get("plan_id"), selection.get("campaign_id"))
    source_ids = {str(row.get("station_id") or "") for row in source["rows"]}
    network_ids = {row["id"] for row in network["stations"]}
    if set(mapping) - source_ids or set(mapping.values()) - network_ids or len(set(mapping.values())) != len(mapping):
        raise ContractError("Explicit station mapping must select distinct existing native stations")
    result = {
        "observation_id": source["id"], "network_id": network["id"],
        "plan_id": plan["id"] if plan and not campaign else None,
        "campaign_id": campaign["revision"]["campaign_id"] if campaign else None,
        "station_mapping": deepcopy(mapping), "title": title,
        "interpretation": interpretation(selection.get("interpretation", {}), source["columns"]),
    }
    return result, network


def _optional(row, metadata, options, field):
    # A deliberately blank optional mapping disables a retained default.
    if field in options["columns"]:
        column = options["columns"][field]
        return (column != ""), row.get("original", {}).get(column) if column else None
    column = metadata.get("columns", {}).get(field)
    if column:
        return column in row.get("original", {}), row.get("original", {}).get(column)
    if field in row:
        return True, row[field]
    if field in metadata:
        return True, metadata[field]
    return False, None


def _day(value):
    if not isinstance(value, str) or date.fromisoformat(value).isoformat() != value:
        raise ValueError("Original date needs one complete ISO calendar day")
    return value


def _row(source, row, options):
    metadata = source.get("metadata", {})
    row_id = _text(row.get("id"), "Original row ID")
    raw = row.get("original")
    if not isinstance(raw, dict):
        raise ContractError("Each native row must retain its original cells")
    picked = {field: _optional(row, metadata, options, field) for field in OPTIONAL_COLUMNS}
    def text(field):
        present, value = picked[field]
        return str(value).strip() if present and value is not None else ""
    station = str(row.get("station_id") or "")
    activity = text("activity") or source["id"] + ":" + row_id
    result = {
        "observation_id": digest({"observation_id": source["id"], "original_record_id": row_id}),
        "original_observation_id": source["id"], "original_record_id": row_id,
        "source_row": row.get("line"), "source_file": deepcopy(source["original"]),
        "original_cells": deepcopy(raw), "original_record": deepcopy(row),
        "station_id": station, "activity_id": activity,
        "activity_identity_basis": "original_activity" if text("activity") else "original_record",
        "date": row.get("period_start"),
        "characteristic": row.get("original_parameter", row.get("parameter")),
        "method": row.get("method"), "unit": row.get("unit"), "original_unit": row.get("unit"),
        "qualifier": str(row.get("qualifier") or "").strip(),
        "result_text": str(row.get("value_text") or ""),
        "result_value": None, "limit_value": None, "lower": None, "upper": None,
        "lower_unbounded": False, "upper_unbounded": False,
        "status": "uninterpreted",
        "sampling_cohort_schema": "upstate.native-observation-sampling-cohort/v1",
    }
    # Preserve field presence, nulls and blank original values in cohort keys.
    names = {
        "fraction": ("fraction", "sample_fraction"),
        "depth": ("depth_value",), "depth_unit": ("depth_unit",),
        "method_authority": ("method_context",),
        "value_type": ("value_type", "result_value_type"),
        "project": ("project_id",), "time": ("time",), "timezone": ("timezone",),
        "comment": ("comment",), "result_depth": ("result_depth_value",),
        "result_depth_unit": ("result_depth_unit",),
    }
    for field, (present, value) in picked.items():
        if not present or field in ("activity", "reporting_limit", "reporting_limit_unit"):
            continue
        for key in names.get(field, (field,)):
            result[key] = deepcopy(value)
    for key in ("time_support", "quantity_basis", "measurement_support"):
        if key in row:
            result[key] = deepcopy(row[key])
    if "species" in row:
        result["speciation"] = deepcopy(row["species"])
    if "method" in row:
        result["method_id"] = deepcopy(row["method"])
    reasons = []
    try:
        _day(result["date"])
        if row.get("period_end") and row["period_end"] != result["date"]:
            reasons.append("Multi-day original support is not a single-day observation")
    except (ValueError, TypeError):
        reasons.append("Original date needs one complete ISO calendar day")
    if metadata.get("value_basis") == "annual_mass_rate":
        reasons.append("Annual mass-rate records remain in their original native load comparison")
    qualifier = result["qualifier"]
    raw_value = result["result_text"].strip()
    inline = INLINE_LIMIT.fullmatch(raw_value)
    direction = ("below" if qualifier in options["below_qualifiers"] else
                 "above" if qualifier in options["above_qualifiers"] else
                 "numeric" if qualifier in options["numeric_qualifiers"] else None)
    if inline:
        inline_direction = "below" if inline[1] in ("<", "<=", "≤") else "above"
        if qualifier and direction != inline_direction:
            reasons.append("Inline limit and original qualifier have different or unreviewed meanings")
        direction = inline_direction
    limit_text, limit_unit = text("reporting_limit"), text("reporting_limit_unit")
    result["limit_unit"] = limit_unit if picked["reporting_limit_unit"][0] else result["unit"]
    if limit_text:
        try:
            result["limit_value"] = _number(limit_text, "Original reporting limit")
        except ValueError as error:
            reasons.append(str(error))
    try:
        if direction in ("below", "above"):
            limit = _number(limit_text or (inline[2] if inline else raw_value), "Original reporting limit")
            unit = result["unit"]
            if not unit and limit_unit and options["use_limit_unit_when_missing"]:
                result["unit"] = limit_unit
                result["unit_origin"] = "Original reporting-limit unit; explicit missing-unit choice"
            if limit_unit and limit_unit != result["unit"]:
                raise ContractError("Reporting-limit and measurement units differ; no conversion was selected")
            if options["nonnegative"] and limit < 0:
                raise ContractError("Negative limit conflicts with selected nonnegative support")
            result["limit_value"] = limit
            result["limit_unit"] = limit_unit or result["unit"]
            if direction == "below":
                result.update(lower=0.0 if options["nonnegative"] else None, upper=limit,
                              lower_unbounded=not options["nonnegative"], status="below_limit")
            else:
                result.update(lower=limit, upper=None, upper_unbounded=True, status="above_limit")
            # No "<" versus "<=" meaning is invented for a textual qualifier.
            if inline:
                result["limit_operator"] = inline[1]
        elif direction == "numeric" and not inline:
            number = _number(raw_value, "Original result")
            if options["nonnegative"] and number < 0:
                raise ContractError("Negative result conflicts with selected nonnegative support")
            result.update(result_value=number, lower=number, upper=number, status="measured")
        else:
            reasons.append("Original qualifier has no explicitly selected numeric or limit meaning: " + repr(qualifier))
    except (ValueError, TypeError) as error:
        reasons.append(str(error))
    if not station or not result["characteristic"] or not result["unit"]:
        reasons.append("Original station, characteristic and measurement unit are required")
    if reasons:
        result["reasons"] = list(dict.fromkeys(reasons))
    return result


def _stations(source, selected, network):
    originals = sorted({str(row.get("station_id") or "") for row in source["rows"] if row.get("station_id")})
    native = {row["id"]: row for row in network["stations"]}
    result = []
    for key in originals:
        target = selected["station_mapping"].get(key, key)
        retained = native.get(target)
        point = retained.get("geometry", {}) if retained else {}
        coords = point.get("coordinates") if point.get("type") == "Point" else None
        item = {"station_id": key, "station_name": key, "longitude": None, "latitude": None,
                "datum": None, "coordinate_origin": "not_received"}
        if coords and len(coords) >= 2:
            item.update(longitude=coords[0], latitude=coords[1], datum="WGS84",
                        coordinate_origin="retained_network_station",
                        coordinate_network_station_id=target,
                        coordinate_network_id=network["id"],
                        coordinate_source_bindings=deepcopy(network.get("source_bindings", {})))
        result.append(item)
    return result


def _document(workspace, source, record_path, selected, network):
    binding = {
        "observation_id": source["id"], "project_id": workspace.project["id"],
        "record_sha256": file_sha256(record_path), "original_file": deepcopy(source["original"]),
        "source_uri": source.get("metadata", {}).get("source_uri"),
        "title": source.get("metadata", {}).get("title", source["id"]),
        "original_mapping": deepcopy(source.get("metadata", {}).get("columns", {})),
        "original_options": deepcopy(source.get("metadata", {})),
        "selection": deepcopy(selected), "row_count": len(source["rows"]),
    }
    rows = [_row(source, row, selected["interpretation"]) for row in source["rows"]]
    if len({row["original_record_id"] for row in rows}) != len(rows):
        raise ContractError("Original native row IDs repeat")
    # An activity is one original station/date. Ambiguous original IDs remain excluded.
    activity_dates = {}
    for row in rows:
        if "reasons" not in row:
            activity_dates.setdefault((row["station_id"], row["activity_id"]), set()).add(row["date"])
    for row in rows:
        if len(activity_dates.get((row["station_id"], row["activity_id"]), set())) > 1:
            row.setdefault("reasons", []).append("Original activity ID refers to more than one date")
    included = [row for row in rows if "reasons" not in row]
    excluded = [row for row in rows if "reasons" in row]
    dates = []
    for row in rows:
        try:
            dates.append(_day(row["date"]))
        except (ValueError, TypeError):
            pass
    if not dates:
        raise ContractError("No original ISO observation date is available; inspect the original import mapping")
    activities = {}
    for row in included:
        key = (row["station_id"], row["activity_id"])
        item = {"station_id": row["station_id"], "activity_id": row["activity_id"], "date": row["date"],
                "activity_identity_basis": row["activity_identity_basis"]}
        if "activity_type" in row:
            item["activity_type"] = row["activity_type"]
        activities.setdefault(key, item)
    value = {
        "schema": observed.CONCENTRATION_SOURCE_SCHEMA, "title": selected["title"],
        "source_edition": digest({"edition": EDITION, "native": binding, "network": digest(network)}),
        "native_observation_binding": binding,
        "source_period": {"start_inclusive": min(dates), "end_inclusive": max(dates)},
        "flow_scope": {"mode": "unavailable", "station_ids": []},
        "flow_availability": deepcopy(FLOW_UNAVAILABLE),
        "stations": _stations(source, selected, network),
        "activities": list(activities.values()), "observations": included, "excluded_observations": excluded,
        "daily_flow": [], "relations": [], "annual_coverage": [], "station_year_coverage": [],
        "monthly_coverage": [], "high_flow_episodes": [], "paired_contrasts": [],
        "interpretation": [
            "Values are original source observations with explicit qualifier and unit choices; censored limits are not measured values.",
            "All original rows, raw cells, original import mapping and the exact original file remain retained; excluded rows carry their individual reasons.",
            "When no original activity identifier is selected, an explicit original_record identity groups that row only; it does not establish a separate field activity or visit.",
            "No daily-flow series was selected or inferred from these observation rows. Flow-linked episodes, event coverage, mass loads and modeled export comparisons are unavailable.",
            "Station assignment uses only an existing native network station with exact identifier or explicit mapping. Network geometry is labeled as such.",
            "Methods, fractions, depth, value type, units, project metadata and declared time/quantity/measurement support remain separate original Sampling cohorts; no unit conversion is performed.",
        ],
    }
    observed._validate(value)
    return value


def _cohorts(context):
    from .monitoring_recommendations import _cohort
    values = {}
    for row in context["observations"]:
        key, fields = _cohort(row)
        item = values.setdefault(key, {"id": key, "fields": fields, "observation_count": 0,
                                      "station_ids": set(), "original_record_ids": []})
        item["observation_count"] += 1
        item["station_ids"].add(row["station_id"])
        item["original_record_ids"].append(row["original_record_id"])
    return [{**item, "station_ids": sorted(item["station_ids"])} for _, item in sorted(values.items())]


def _preview(workspace, selection):
    if not isinstance(selection, dict):
        raise ContractError("The native observation selection must be an object")
    source, record_path = _native(workspace, selection.get("observation_id"))
    selected, network = _selection(workspace, selection, source)
    document = _document(workspace, source, record_path, selected, network)
    body = canonical_bytes(document)
    binding = {"source_id": None, "source_collection_id": None, "source_record_id": None,
               "title": selected["title"], "filename": "observed-context.json",
               "bytes": len(body), "object_sha256": hashlib.sha256(body).hexdigest()}
    context = observed._preview(workspace, value=document, binding=binding,
        network_id=selected["network_id"], plan_id=selected["plan_id"],
        campaign_id=selected["campaign_id"], station_mapping=selected["station_mapping"], title=selected["title"])
    identity = digest({"edition": EDITION, "selection": selected, "document": binding["object_sha256"],
                       "context": context})
    result = {"id": identity, "selection": selected, "source": document["native_observation_binding"],
              "context": context, "cohorts": _cohorts(context),
              "summary": {**context["summary"], "included_source_rows": len(document["observations"]),
                          "excluded_source_rows": len(document["excluded_observations"]),
                          "status_counts": dict(Counter(row["status"] for row in document["observations"]))}}
    return result, document, source, record_path


def preview(workspace, *, selection):
    return _preview(workspace, selection)[0]


def verify_binding(workspace, binding):
    if not isinstance(binding, dict):
        raise ContractError("Native observation provenance must be a retained object")
    identifier(binding.get("observation_id"))
    identifier(binding.get("record_sha256"))
    if binding.get("project_id") != workspace.project["id"]:
        return  # Foreign ordinary source remains complete in its original CAS companions.
    source, path = _native(workspace, binding["observation_id"])
    if (file_sha256(path) != binding["record_sha256"]
            or source["original"] != binding.get("original_file")
            or len(source["rows"]) != binding.get("row_count")
            or source.get("metadata", {}).get("columns", {}) != binding.get("original_mapping")
            or source.get("metadata", {}) != binding.get("original_options")):
        raise ContractError("The saved native observation binding differs from its original import")


def prepare(workspace, *, selection, expected_preview_id):
    result, document, source, record_path = _preview(workspace, selection)
    if identifier(expected_preview_id) != result["id"]:
        raise ContractError("The original observation, network or interpretation changed; preview the same selection again")
    source_id = "native-observations-" + result["id"]
    with tempfile.TemporaryDirectory(prefix="monitoring-native-context-") as directory:
        folder = Path(directory)
        (folder / "observed-context.json").write_bytes(canonical_bytes(document))
        original = relative_file(workspace.root, source["original"]["object"])
        # Byte-exact source files; neither the native importer nor its record is modified.
        (folder / "original.csv").write_bytes(original.read_bytes())
        (folder / "original-native-observation.json").write_bytes(record_path.read_bytes())
        (folder / "native-selection.json").write_bytes(canonical_bytes(result["selection"]))
        manifest = {"schema": "upstate.sources/v1", "title": result["selection"]["title"],
            "notes": document["interpretation"], "entries": [{
                "id": source_id, "title": result["selection"]["title"],
                "uri": "urn:upstate:native-observation-context:" + workspace.project["id"] + ":" + result["id"],
                "vintage": document["source_period"]["end_inclusive"],
                "kind": "document", "role": "monitoring_observed_context",
                "path": "observed-context.json", "sha256": result["context"]["source_binding"]["object_sha256"],
                "metadata": {"native_observation_id": source["id"], "context_schema": document["schema"],
                             "preview_id": result["id"], "flow_availability": "not_received"},
                "companions": [
                    {"path": "original.csv", "sha256": source["original"]["sha256"]},
                    {"path": "original-native-observation.json", "sha256": document["native_observation_binding"]["record_sha256"]},
                    {"path": "native-selection.json", "sha256": digest(result["selection"])},
                ],
            }]}
        (folder / "manifest.json").write_bytes(canonical_bytes(manifest))
        verify_binding(workspace, document["native_observation_binding"])
        collection = workspace.import_sources(folder / "manifest.json")
    selected = result["selection"]
    actual = observed.preview(workspace, source_collection_id=collection["id"], source_id=source_id,
        network_id=selected["network_id"], plan_id=selected["plan_id"], campaign_id=selected["campaign_id"],
        station_mapping=selected["station_mapping"], title=selected["title"])
    if ({k: v for k, v in actual.items() if k != "source_binding"}
            != {k: v for k, v in result["context"].items() if k != "source_binding"}):
        raise ContractError("Native context projection changed during source preparation")
    saved = workspace._save(observed.COLLECTION, actual)
    return observed.inspect(workspace, saved["id"])


def main():
    from .workspace import Workspace
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--workspace", required=True)
    commands = parser.add_subparsers(dest="command", required=True)
    commands.add_parser("catalog")
    for name in ("preview", "prepare"):
        command = commands.add_parser(name)
        command.add_argument("--selection", type=Path, required=True)
        if name == "prepare":
            command.add_argument("--expected-preview-id", required=True)
    args = parser.parse_args()
    workspace = Workspace(args.workspace)
    if args.command == "catalog":
        result = catalog(workspace)
    else:
        selection = json.loads(args.selection.read_text(encoding="utf-8"))
        result = (preview(workspace, selection=selection) if args.command == "preview" else
                  prepare(workspace, selection=selection, expected_preview_id=args.expected_preview_id))
    print(json.dumps(result, ensure_ascii=False, indent=2, allow_nan=False))


if __name__ == "__main__":
    main()

