                   *community_transfer.IMMUTABLE_KINDS, *customer_review_transfer.IMMUTABLE_KINDS, *terrain_transfer.IMMUTABLE_KINDS,
                   *management_transfer.IMMUTABLE_KINDS)
DOCUMENTS = {
